    "draw_sprite_part_ext_rot": "function draw_sprite_part_ext_rot(arg0, arg1, arg2, arg3, arg4, arg5, arg6, arg7, arg8, arg9, arg10, arg11, arg12)\n{\n    if (arg2 < 0)\n        arg2 = 0;\n    \n    if (arg3 < 0)\n        arg3 = 0;\n    \n    var __xoffset = sprite_get_xoffset(arg0) * arg8;\n    var __yoffset = sprite_get_yoffset(arg0) * arg9;\n    var __newx = arg2 * arg8;\n    var __newy = arg3 * arg9;\n    var __theta = point_direction(__xoffset, __yoffset, __newx, __newy);\n    var __radius = point_distance(__xoffset, __yoffset, __newx, __newy);\n    __theta += arg10;\n    var __xx = arg6 + lengthdir_x(__radius, __theta);\n    var __yy = arg7 + lengthdir_y(__radius, __theta);\n    draw_sprite_general(arg0, arg1, arg2, arg3, (arg4 / arg8) - arg2, (arg5 / arg9) - arg3, __xx, __yy, arg8, arg9, arg10, arg11, arg11, arg11, arg11, arg12);\n}\n",
    "Vector2": "function Vector2(arg0 = 0, arg1 = 0) constructor\n{\n    static add = function(arg0)\n    {\n        x += arg0.x;\n        y += arg0.y;\n    };\n    \n    static scale = function(arg0)\n    {\n        x *= arg0.x;\n        y *= arg0.y;\n    };\n    \n    x = arg0;\n    y = arg1;\n    \n    direction = function(arg0, arg1)\n    {\n        return point_direction(0, 0, arg0, arg1);\n    };\n    \n    magnitude = function(arg0, arg1)\n    {\n        return point_distance(0, 0, arg0, arg1);\n    };\n    \n    normalized = function(arg0, arg1)\n    {\n        var __len = point_distance(0, 0, arg0, arg1);\n        \n        if (arg0 == 0 && arg1 == 0)\n            return new Vector2();\n        \n        return new Vector2(arg0 / __len, arg1 / __len);\n    };\n}\n\nfunction getxy(arg0)\n{\n    return new Vector2(arg0.x, arg0.y);\n}\n\nfunction setxy_v2(arg0)\n{\n    x = arg0.x;\n    y = arg0.y;\n}\n",
    "scr_inverselerp": "function inverselerp(arg0, arg1, arg2)\n{\n    if (arg1 == arg0)\n        return 0;\n    \n    return (arg2 - arg0) / (arg1 - arg0);\n}\n\nfunction scr_inverselerp(arg0, arg1, arg2)\n{\n    if (arg1 == arg0)\n        return 0;\n    \n    return (arg2 - arg0) / (arg1 - arg0);\n}\n",
    "scr_draw_in_box_begin": "function scr_draw_in_box_begin()\n{\n    if (!instance_exists(obj_growtangle))\n        exit;\n    \n    gpu_set_blendenable(false);\n    gpu_set_colorwriteenable(false, false, false, true);\n    draw_set_alpha(0);\n    ossafe_fill_rectangle(camerax(), cameray(), camerax() + 640, cameray() + 480);\n    draw_set_alpha(1);\n    ossafe_fill_rectangle(gt_minx() + 5, gt_miny() + 5, gt_maxx() - 4, gt_maxy() - 4);\n    gpu_set_blendenable(true);\n    gpu_set_colorwriteenable(true, true, true, true);\n    gpu_set_blendmode_ext(bm_dest_alpha, bm_inv_dest_alpha);\n    gpu_set_alphatestenable(true);\n    gpu_set_alphatestref(1);\n}\n\nfunction scr_draw_in_box_ext_begin(arg0, arg1)\n{\n    if (!instance_exists(obj_growtangle))\n        exit;\n    \n    gpu_set_blendenable(false);\n    gpu_set_colorwriteenable(false, false, false, true);\n    draw_set_alpha(0);\n    ossafe_fill_rectangle(camerax(), cameray(), camerax() + 640, cameray() + 480);\n    draw_set_alpha(1);\n    ossafe_fill_rectangle((gt_minx() + 5) - arg0, (gt_miny() + 5) - arg1, (gt_maxx() - 4) + arg0, (gt_maxy() - 4) + arg1);\n    gpu_set_blendenable(true);\n    gpu_set_colorwriteenable(true, true, true, true);\n    gpu_set_blendmode_ext(bm_dest_alpha, bm_inv_dest_alpha);\n    gpu_set_alphatestenable(true);\n    gpu_set_alphatestref(1);\n}\n",
