    "scr_bullet_create": "function scr_bullet_create(arg0, arg1, arg2)\n{\n    var __newbullet = instance_create(arg0, arg1, arg2);\n    __newbullet.damage = damage;\n    __newbullet.target = target;\n    \n    if (variable_instance_exists(self, \"element\"))\n        __newbullet.element = element;\n    \n    return __newbullet;\n}\n",
    "scr_dark_marker_animated": "function scr_dark_marker_animated()\n{\n    var x_pos = argument[0];\n    var y_pos = argument[1];\n    var sprite = argument[2];\n    var anim_speed = (argument_count > 3) ? argument[3] : 0.2;\n    thismarker = instance_create(x_pos, y_pos, obj_marker);\n    \n    with (thismarker)\n    {\n        sprite_index = sprite;\n        image_speed = anim_speed;\n        image_xscale = 2;\n        image_yscale = 2;\n        scr_depth();\n    }\n    \n    return thismarker;\n}\n",
    "scr_enemy_animation": "function scr_enemy_animation(arg0, arg1 = 0, arg2 = 0, arg3 = false)\n{\n    return scr_enemy_animation_custom(1035, arg0, arg1, arg2, arg3);\n}\n\nfunction scr_enemy_animation_custom(arg0, arg1, arg2 = 0, arg3 = 0, arg4 = false)\n{\n    if (arg4)\n    {\n        arg2 *= image_xscale;\n        arg3 *= image_yscale;\n    }\n    \n    var _monster = global.monsterinstance[creator];\n    var _anim_obj = instance_create(x + arg2, y + arg3, arg0);\n    _anim_obj.creator = creator;\n    _monster.visible = 0;\n    _anim_obj.sprite_index = arg1;\n    _anim_obj.image_xscale = _monster.image_xscale;\n    _anim_obj.image_yscale = _monster.image_yscale;\n    return _anim_obj;\n}\n",
    "scr_getlaunchdirection": "function scr_getlaunchdirection(arg0, arg1, arg2, arg3)\n{\n    if ((sqr(arg0) / arg2) <= arg1)\n        return 45;\n    \n    var __resultangle = radtodeg(arcsin((arg1 * arg2) / sqr(arg0))) / 2;\n    \n    if (arg3 >= 1)\n        return 90 - __resultangle;\n    else if (arg3 <= -1)\n        return __resultangle;\n    else\n        return choose(__resultangle, 90 - __resultangle);\n}\n",
