    "scr_marker_ext": "function scr_marker_ext(arg0, arg1, arg2, arg3 = 1, arg4 = 1, arg5 = 0, arg6 = 0, arg7 = 16777215, arg8 = depth, arg9 = false, arg10 = -1, arg11 = 1)\n{\n    var thismarker = instance_create(arg0, arg1, obj_marker);\n    \n    with (thismarker)\n    {\n        depth = arg8;\n        sprite_index = arg2;\n        image_speed = arg5;\n        image_xscale = arg3;\n        image_yscale = arg4;\n        image_index = arg6;\n        image_blend = arg7;\n        image_alpha = arg11;\n        \n        if (arg9)\n            scr_depth();\n    }\n    \n    if (arg10 > 0)\n        scr_doom(thismarker, arg10);\n    \n    return thismarker;\n}\n",
    "scr_tenna_add_score": "function scr_tenna_add_score(arg0)\n{\n    if (i_ex(obj_tenna_enemy_bg))\n    {\n        var _multiplier = 1;\n        var _multi_minigame_adjustment = 1;\n        \n        if (obj_tenna_enemy.minigameactivated)\n        {\n            if (obj_tenna_enemy.minigamecount >= 6)\n                _multi_minigame_adjustment = 0.65;\n            \n            _multiplier = (obj_tenna_enemy.pointsmultiplierthisturn + obj_tenna_enemy.pointsmultiplier) * _multi_minigame_adjustment;\n            obj_tenna_enemy.pointsmultiplierthisturn -= 1;\n            \n            if (obj_tenna_enemy.pointsmultiplierthisturn < 1)\n                obj_tenna_enemy.pointsmultiplierthisturn = 1;\n        }\n        \n        if (!i_ex(obj_tenna_zoom))\n            obj_tenna_enemy_bg.addscore += round(arg0 * _multiplier);\n        else if (i_ex(obj_tenna_minigame_ui))\n            obj_tenna_minigame_ui.myscore += round(arg0 * _multiplier);\n    }\n}\n",
    "get_inputs": "function get_inputs(arg0)\n{\n    if (arg0)\n    {\n        key_left = left_h();\n        key_right = right_h();\n        key_up = up_h();\n        key_down = down_h();\n        press_left = left_p();\n        press_right = right_p();\n        press_up = up_p();\n        press_down = down_p();\n        vinput = key_down - key_up;\n        hinput = key_right - key_left;\n        press_jump = button2_p();\n        key_jump = button2_h();\n        press_attack = button1_p();\n        key_attack = button1_h();\n    }\n    else\n    {\n        vinput = 0;\n        hinput = 0;\n        key_left = false;\n        key_right = false;\n        press_jump = false;\n        key_jump = false;\n        press_attack = false;\n        key_attack = false;\n    }\n}\n",
    "scr_wrap_new": "function scr_wrap_new()\n{\n    var _val = argument[0];\n    var _max = argument[2];\n    var _min = argument[1];\n    \n    if ((_val % 1) == 0)\n    {\n        while (_val > _max || _val < _min)\n        {\n            if (_val > _max)\n            {\n                _val = (_min + _val) - _max - 1;\n            }\n            else if (_val < _min)\n            {\n                _val = ((_max + _val) - _min) + 1;\n            }\n            else\n            {\n            }\n        }\n        \n        return _val;\n    }\n    else\n    {\n        var _old = argument[0] + 1;\n        \n        while (_val != _old)\n        {\n            _old = _val;\n            \n            if (_val < _min)\n            {\n                _val = _max - (_min - _val);\n            }\n            else if (_val > _max)\n            {\n                _val = _min + (_val - _max);\n            }\n            else\n            {\n            }\n        }\n        \n        return _val;\n    }\n}\n",
