    "scr_depth_board": "function scr_depth_board()\n{\n    depth = 1000000 - ((y * 10) + ((sprite_height - sprite_yoffset) * 10));\n}\n\nfunction scr_board_depth()\n{\n    scr_depth_board();\n}\n",
    "scr_board_afterimage": "function scr_board_afterimage()\n{\n    var afterimage = instance_create(x, y, obj_board_afterimage);\n    afterimage.depth = depth;\n    afterimage.sprite_index = sprite_index;\n    afterimage.image_index = image_index;\n    afterimage.image_speed = image_speed;\n    afterimage.image_xscale = image_xscale;\n    afterimage.image_yscale = image_yscale;\n    afterimage.image_angle = image_angle;\n    \n    if (argument_count >= 1)\n        afterimage.type = argument0;\n    \n    if (argument_count >= 2)\n        afterimage.length = argument1;\n    \n    if (argument_count >= 3)\n        afterimage.flickerrate = argument2;\n    \n    return afterimage;\n}\n",
    "scr_board_caterpillar_interpolate_ralsei": "function scr_board_caterpillar_interpolate_ralsei()\n{\n    var _ralsei = obj_board_controller.ralsei_object;\n    \n    if (_ralsei != -1)\n    {\n        with (_ralsei)\n        {\n            for (i = 0; i < 75; i += 1)\n            {\n                remx[i] = x;\n                remy[i] = y;\n                facing[i] = 0;\n            }\n        }\n        \n        var _a = 0;\n        var _dir = point_direction(_ralsei.x, _ralsei.y, x, y);\n        \n        repeat (_ralsei.ralsei_target)\n        {\n            _ralsei.remx[_a] = lerp(obj_board_controller.kris_object.x, _ralsei.x, _a / _ralsei.ralsei_target);\n            _ralsei.remy[_a] = lerp(obj_board_controller.kris_object.y, _ralsei.y, _a / _ralsei.ralsei_target);\n            \n            if (_dir >= 45 && _dir < 135)\n                _ralsei.facingdir[_a] = 2;\n            else if (_dir >= 135 && _dir < 225)\n                _ralsei.facingdir[_a] = 3;\n            else if (_dir >= 225 && _dir < 315)\n                _ralsei.facingdir[_a] = 0;\n            else if (_dir >= 315 || _dir < 45)\n                _ralsei.facingdir[_a] = 1;\n            \n            _a++;\n        }\n    }\n}\n",
    "scr_board_caterpillar_interpolate": "function scr_board_caterpillar_interpolate()\n{\n    var _____kris = 0;\n    \n    with (obj_mainchara_board)\n    {\n        if (name == \"kris\")\n            _____kris = id;\n    }\n    \n    if (_____kris != 0)\n    {\n        remx[0] = _____kris.x;\n        remy[0] = _____kris.y;\n        \n        for (var __rempos = 75; __rempos > 0; __rempos -= 1)\n        {\n            remx[__rempos] = lerp(_____kris.x, x, __rempos / 75);\n            remy[__rempos] = lerp(_____kris.y, y + 6, __rempos / 75);\n        }\n    }\n}\n",
    "scr_pathfind_to_closest_point_32x32": "function scr_pathfind_to_closest_point_32x32(arg0, arg1, arg2, arg3, arg4)\n{\n    with (obj_mainchara_board)\n    {\n        if (name == arg0)\n        {\n            allow_diagonals = arg4;\n            var __destx = arg1 + 16;\n            var __desty = arg2 + 16;\n            \n            if (arg1 < 12 && arg2 < 8)\n            {\n                __destx = 128 + (32 * arg1) + 16;\n                __desty = 64 + (32 * arg2) + 16;\n            }\n            \n            var dist = 999;\n            var found_spot = false;\n            \n            if (mp_grid_path(global.grid, path, x + 16, y + 16, __destx + 2, __desty - 32, arg4) == 1)\n            {\n                if (distance_to_point(__destx + 2, __desty - 32) < dist)\n                {\n                    dist = distance_to_point(__destx, __desty - 32);\n                    path_target_x = __destx + 2;\n                    path_target_y = __desty - 32;\n                    \n                    if (arg3 == -1)\n                        grab_dir = 0;\n                    \n                    found_spot = true;\n                }\n            }\n            \n            if (mp_grid_path(global.grid, path, x + 16, y + 16, __destx + 34, __desty, arg4) == 1)\n            {\n                if (distance_to_point(__destx + 34, __desty) < dist)\n                {\n                    dist = distance_to_point(__destx + 34, __desty);\n                    path_target_x = __destx + 34;\n                    path_target_y = __desty;\n                    \n                    if (arg3 == -1)\n                        grab_dir = 3;\n                    \n                    found_spot = true;\n                }\n            }\n            \n            if (mp_grid_path(global.grid, path, x + 16, y + 16, __destx - 32, __desty, arg4) == 1)\n            {\n                if (distance_to_point(__destx - 32, __desty) < dist)\n                {\n                    dist = distance_to_point(__destx - 32, __desty);\n                    path_target_x = __destx - 32;\n                    path_target_y = __desty;\n                    \n                    if (arg3 == -1)\n                        grab_dir = 1;\n                    \n                    found_spot = true;\n                }\n            }\n            \n            if (mp_grid_path(global.grid, path, x + 16, y + 16, __destx, __desty + 30, arg4) == 1)\n            {\n                if (distance_to_point(__destx, __desty + 30) < dist)\n                {\n                    dist = distance_to_point(__destx, __desty + 30);\n                    path_target_x = __destx + 2;\n                    path_target_y = __desty + 30;\n                    \n                    if (arg3 == -1)\n                        grab_dir = 2;\n                    \n                    found_spot = true;\n                }\n            }\n            \n            if (found_spot == true)\n            {\n                path_end();\n                is_moving_timer = 0;\n                is_moving = true;\n                \n                if (arg0 == \"ralsei\")\n                    follow = false;\n                \n                path_end_facing = grab_dir;\n            }\n            else\n            {\n                show_debug_message(\"PATHFINDING ERROR 5: cannot path to target location\");\n            }\n        }\n    }\n}\n",
    "scr_board_blcon": "function scr_board_blcon(arg0, arg1, arg2)\n{\n    with (obj_board_marker)\n    {\n        if (sprite_index == arg2)\n            instance_destroy();\n    }\n    \n    var nolift = instance_create(arg0, arg1, obj_board_marker);\n    nolift.sprite_index = arg2;\n    nolift.image_speed = 0.2;\n    nolift.image_index = 1;\n    nolift.vspeed = -2.8;\n    nolift.gravity = 0.2;\n    nolift.depth = depth - 100;\n    \n    if (nolift.y <= 64)\n        nolift.y = 64;\n    \n    scr_darksize(nolift);\n    scr_doom(nolift, 20);\n    \n    with (nolift)\n        scr_delay_var(\"gravity\", 0, 15);\n    \n    with (nolift)\n        scr_delay_var(\"vspeed\", 0, 15);\n    \n    snd_stop(snd_error);\n    snd_play(snd_error);\n}\n",
