    "ossafe_game_end": "function ossafe_game_end()\n{\n    if (!global.is_console)\n        game_end();\n    else\n        game_restart_true();\n}\n",
    "scr_gamepad_axis_check": "function scr_gamepad_axis_check(arg0, arg1)\n{\n    axis_value = obj_time.axis_value;\n    __returnvalue = 0;\n    \n    if (arg1 == 0)\n    {\n        if (gamepad_axis_value(arg0, gp_axislv) >= axis_value)\n            __returnvalue = 1;\n    }\n    \n    if (arg1 == 1)\n    {\n        if (gamepad_axis_value(arg0, gp_axislh) >= axis_value)\n            __returnvalue = 1;\n    }\n    \n    if (arg1 == 2)\n    {\n        if (gamepad_axis_value(arg0, gp_axislv) <= -axis_value)\n            __returnvalue = 1;\n    }\n    \n    if (arg1 == 3)\n    {\n        if (gamepad_axis_value(arg0, gp_axislh) <= -axis_value)\n            __returnvalue = 1;\n    }\n    \n    return __returnvalue;\n}\n",
    "string_hash_to_newline_ex": "function string_hash_to_newline_ex(arg0)\n{\n    if (string_pos(\"`\", arg0) > 0)\n    {\n        var __newstring = string_replace(arg0, \"`#\", \"<hash>\");\n        __newstring = string_hash_to_newline(__newstring);\n        return string_replace(__newstring, \"<hash>\", \"#\");\n    }\n    else\n    {\n        return string_hash_to_newline(arg0);\n    }\n}\n",
    "hexcolor": "function hexcolor(arg0)\n{\n    return ((arg0 & 255) << 16) | (arg0 & 65280) | ((arg0 >> 16) & 255);\n}\n",
    "scr_rotatevector": "function scr_rotatevector(arg0, arg1)\n{\n    if (arg1 == 0)\n        return arg0;\n    \n    var _dir = point_direction(0, 0, arg0.x, arg0.y);\n    var _len = point_distance(0, 0, arg0.x, arg0.y);\n    arg0.x = lengthdir_x(_len, _dir + arg1);\n    arg0.y = lengthdir_y(_len, _dir + arg1);\n    return arg0;\n}\n\nfunction scr_rotatevector_xy(arg0, arg1, arg2)\n{\n    var _tempVector = \n    {\n        x: arg0,\n        y: arg1\n    };\n    \n    if (arg2 == 0)\n        return _tempVector;\n    \n    var _dir = point_direction(0, 0, arg0, arg1);\n    var _len = point_distance(0, 0, arg0, arg1);\n    _tempVector.x = lengthdir_x(_len, _dir + arg2);\n    _tempVector.y = lengthdir_y(_len, _dir + arg2);\n    return _tempVector;\n}\n\nfunction scr_dir_to_vector(arg0)\n{\n    var __dir = arg0[0];\n    var __len = 1;\n    \n    if (argument_count > 1)\n        __len = arg0[1];\n    \n    return new Vector2(lengthdir_x(__dir, __len), lengthdir_y(__dir, __len));\n}\n\nfunction scr_rotatevector_around(arg0, arg1, arg2)\n{\n    var __dir = Vector2_direction(arg1, arg0);\n    var __len = Vector2_distance(arg1, arg0);\n    arg0.x = arg1.x + lengthdir_x(__len, __dir + arg2);\n    arg0.y = arg1.y + lengthdir_y(__len, __dir + arg2);\n    return arg0;\n}\n\nfunction Vector2_distance(arg0, arg1)\n{\n    return point_distance(arg0.x, arg0.y, arg1.x, arg1.y);\n}\n\nfunction Vector2_direction(arg0, arg1)\n{\n    return point_direction(arg0.x, arg0.y, arg1.x, arg1.y);\n}\n",
    "draw_sprite_ext_glow": "function draw_sprite_ext_glow()\n{\n    var color = (argument_count > 9) ? argument[9] : c_white;\n    var blend = (color != c_white) ? merge_color(argument[7], color, glow) : argument[7];\n    \n    if (glow < 1)\n        draw_sprite_ext(argument[0], argument[1], argument[2], argument[3], argument[4], argument[5], argument[6], blend, argument[8]);\n    \n    if (glow > 0)\n    {\n        if (color == c_white)\n            draw_set_blend_mode(bm_add);\n        \n        d3d_set_fog(true, color, 0, 1);\n        draw_sprite_ext(argument[0], argument[1], argument[2], argument[3], argument[4], argument[5], argument[6], argument[7], glow);\n        d3d_set_fog(false, c_black, 0, 0);\n        \n        if (color == c_white)\n            draw_set_blend_mode(bm_normal);\n    }\n}\n",
