    "scr_copybullet": "function scr_copybullet(arg0 = 0, arg1 = true)\n{\n    if (arg0 == 0)\n        arg0 = id;\n    \n    with (arg0)\n    {\n        bullet_values = \n        {\n            gravity: gravity,\n            speed: speed,\n            direction: direction,\n            gravity_direction: gravity_direction,\n            friction: friction,\n            image_blend: image_blend,\n            destroyonhit: destroyonhit\n        };\n        \n        if (arg1)\n        {\n            gravity = 0;\n            speed = 0;\n            friction = 0;\n            gravity_direction = 270;\n            direction = 0;\n            destroyonhit = false;\n        }\n    }\n}\n\nfunction scr_pastebullet(arg0 = 0)\n{\n    if (arg0 == 0)\n        arg0 = id;\n    \n    with (arg0)\n    {\n        if (v_ex(\"bullet_values\"))\n        {\n            gravity = bullet_values.gravity;\n            gravity_direction = bullet_values.gravity_direction;\n            friction = bullet_values.friction;\n            direction = bullet_values.direction;\n            speed = bullet_values.speed;\n            image_blend = bullet_values.image_blend;\n            destroyonhit = bullet_values.destroyonhit;\n        }\n        else\n        {\n            debug_print(\"can't load values w/o saved values!!!!!\");\n        }\n    }\n}\n",
    "gt_inbounds": "function gt_inbounds(arg0, arg1)\n{\n    return gt_inbounds_tol(arg0, arg1, 0);\n}\n\nfunction gt_inbounds_tol(arg0, arg1, arg2)\n{\n    return arg0 >= (gt_minx() - arg2) && arg0 <= (gt_maxx() + arg2) && arg1 >= (gt_miny() - arg2) && arg1 <= (gt_maxy() + arg2);\n}\n\nfunction gt_inward(arg0, arg1, arg2)\n{\n    return gt_inward_tol(arg0, arg1, arg2, 0);\n}\n\nfunction gt_inward_tol(arg0, arg1, arg2, arg3)\n{\n    if (gt_inbounds_tol(arg0, arg1, arg3))\n        return true;\n    else if (arg0 < (gt_minx() - arg3) && abs(angle_difference(arg2, 0) > 90))\n        return false;\n    else if (arg0 > (gt_maxx() + arg3) && abs(angle_difference(arg2, 180) > 90))\n        return false;\n    else if (arg1 < (gt_miny() - arg3) && abs(angle_difference(arg2, 270) > 90))\n        return false;\n    else if (arg1 > (gt_maxy() + arg3) && abs(angle_difference(arg2, 90) > 90))\n        return false;\n    \n    return true;\n}\n",
    "scr_ease_inout": "function scr_ease_inout(arg0, arg1)\n{\n    if (arg1 < -3 || arg1 > 7)\n        return arg0;\n    \n    if (arg1 == -3)\n        return ease_inout_bounce(arg0, 0, 1, 1);\n    else if (arg1 == -2)\n        return ease_inout_elastic(arg0, 0, 1, 1);\n    else if (arg1 == -1)\n        return ease_inout_back(arg0, 0, 1, 1);\n    else if (arg1 == 1)\n        return -0.5 * cos((pi * arg0) - 1);\n    else if (arg1 == 0)\n        return arg0;\n    \n    arg0 *= 2;\n    \n    if (arg0 < 1)\n    {\n        return 0.5 * scr_ease_in(arg0, arg1);\n    }\n    else\n    {\n        arg0--;\n        return 0.5 * (scr_ease_out(arg0, arg1) + 1);\n    }\n}\n",
    "scr_lines_intersect": "function scr_lines_intersect()\n{\n    var ua = 0;\n    var ux = argument[2] - argument[0];\n    var uy = argument[3] - argument[1];\n    var vx = argument[6] - argument[4];\n    var vy = argument[7] - argument[5];\n    var wx = argument[0] - argument[4];\n    var wy = argument[1] - argument[5];\n    var ud = (vy * ux) - (vx * uy);\n    \n    if (ud != 0)\n    {\n        ua = ((vx * wy) - (vy * wx)) / ud;\n        \n        if (argument[8])\n        {\n            var ub = ((ux * wy) - (uy * wx)) / ud;\n            \n            if (ua < 0 || ua > 1 || ub < 0 || ub > 1)\n                ua = 0;\n        }\n    }\n    \n    return ua;\n}\n",
