    "scr_anglechange": "function scr_anglechange(arg0, arg1, arg2)\n{\n    arg0 = median(-arg2, arg2, angle_difference(arg1, arg0));\n    return arg0;\n}\n",
    "scr_play_susie_recording": "function scr_play_susie_recording(arg0)\n{\n    with (obj_mainchara_board)\n    {\n        if (name == \"susie\")\n        {\n            susierecordcon = 2;\n            susierecordcount = 0;\n            susierecordstring = arg0;\n            susierecordsave = false;\n        }\n    }\n}\n",
    "scr_board_checklocation": "function scr_board_checklocation()\n{\n    var _name = argument0;\n    var _xloc = argument1;\n    var _yloc = argument2;\n    \n    if (_xloc < 12)\n        _xloc = board_tilex(_xloc);\n    \n    if (_yloc < 12)\n        _yloc = board_tiley(_yloc);\n    \n    var _tol = 4;\n    \n    if (argument_count == 4)\n        _tol = argument3;\n    \n    var targ = 0;\n    \n    with (obj_mainchara_board)\n    {\n        if (name == _name)\n            targ = id;\n    }\n    \n    if (!i_ex(targ))\n    {\n        debug_message(\"target does not exist\");\n        return false;\n    }\n    \n    if (abs(targ.x - _xloc) < _tol && abs(targ.y - _yloc) < _tol)\n        return true;\n}\n",
    "scr_play_ralsei_recording": "function scr_play_ralsei_recording(arg0)\n{\n    with (obj_mainchara_board)\n    {\n        if (name == \"ralsei\")\n        {\n            susierecordcon = 2;\n            susierecordcount = 0;\n            susierecordstring = arg0;\n            susierecordsave = false;\n        }\n    }\n}\n",
    "tennahere": "function tennahere()\n{\n    if (global.flag[1022] == 0)\n        return true;\n    else\n        return false;\n}\n",
    "ease_out_bounce": "function ease_out_bounce(arg0, arg1, arg2, arg3)\n{\n    arg0 /= arg3;\n    \n    if (arg0 < 0.36363636363636365)\n    {\n        return (arg2 * (7.5625 * arg0 * arg0)) + arg1;\n    }\n    else if (arg0 < 0.7272727272727273)\n    {\n        arg0 -= 0.5454545454545454;\n        return (arg2 * ((7.5625 * arg0 * arg0) + 0.75)) + arg1;\n    }\n    else if (arg0 < 0.9090909090909091)\n    {\n        arg0 -= 0.8181818181818182;\n        return (arg2 * ((7.5625 * arg0 * arg0) + 0.9375)) + arg1;\n    }\n    else\n    {\n        arg0 -= 0.9545454545454546;\n        return (arg2 * ((7.5625 * arg0 * arg0) + 0.984375)) + arg1;\n    }\n}\n",
    "scr_inventoryspace": "function scr_inventoryspace()\n{\n    var freespace = 0;\n    var inventoryspace = 12;\n    \n    for (var i = 0; i < inventoryspace; i++)\n    {\n        if (global.item[i] == 0)\n            freespace++;\n    }\n    \n    debug_message(\"from \" + object_get_name(object_index) + \": scr_inventoryspace(): free inventory slots=\" + string(freespace));\n    return freespace;\n}\n\nfunction scr_pocketspace()\n{\n    var pocketspace = 0;\n    \n    for (var i = 0; i < global.flag[64]; i++)\n    {\n        if (global.pocketitem[i] == 0)\n            pocketspace++;\n    }\n    \n    debug_message(\"from \" + object_get_name(object_index) + \": scr_pocketspace(): free pocket slots=\" + string(pocketspace));\n    return pocketspace;\n}\n",
    "scr_msgno_end": "function scr_msgno_end(arg0 = 0)\n{\n    if (i_ex(obj_writer))\n    {\n        with (obj_writer)\n        {\n            if (msgno == arg0)\n            {\n                if (reachedend)\n                    return true;\n                else\n                    return false;\n            }\n        }\n    }\n    else\n    {\n        return true;\n    }\n}\n",
    "scr_getmsgno_d": "function scr_getmsgno_d()\n{\n    if (instance_exists(obj_dialoguer) && instance_exists(obj_dialoguer.writer))\n        return obj_dialoguer.writer.msgno;\n}\n",
    "scr_susiezilla_hiteffect": "function scr_susiezilla_hiteffect(arg0)\n{\n    var _hit = arg0;\n    var _hitmarker = scr_dark_marker(round((_hit.myxcenter + myxcenter) / 2), round((_hit.myycenter + myycenter) / 2), spr_dogcar_hit);\n    scr_doom(_hitmarker, 4);\n    var hitscale = myhitscale;\n    \n    if (_hit.myhitscale > hitscale)\n        hitscale = _hit.myhitscale;\n    \n    scr_scale(hitscale, _hitmarker);\n    scr_lerpvar_instance(_hitmarker, \"image_xscale\", hitscale, 1, 4);\n    scr_lerpvar_instance(_hitmarker, \"image_yscale\", hitscale, 1, 4);\n    _hitmarker.depth = depth - 100;\n    return _hitmarker;\n}\n",
