    "scr_ja_alphanumericarray": "function scr_ja_alphanumericarray()\n{\n    var alphanumericarray = [\"ア\", \"イ\", \"ウ\", \"エ\", \"オ\", \"カ\", \"キ\", \"ク\", \"ケ\", \"コ\", \"ガ\", \"ギ\", \"グ\", \"ゲ\", \"ゴ\", \"サ\", \"シ\", \"ス\", \"セ\", \"ソ\", \"ザ\", \"ジ\", \"ズ\", \"ゼ\", \"ゾ\", \"タ\", \"チ\", \"ツ\", \"テ\", \"ト\", \"ダ\", \"ヂ\", \"ヅ\", \"デ\", \"ド\", \"ナ\", \"ニ\", \"ヌ\", \"ネ\", \"ノ\", \"ハ\", \"ヒ\", \"フ\", \"ヘ\", \"ホ\", \"バ\", \"ビ\", \"ブ\", \"ベ\", \"ボ\", \"パ\", \"ピ\", \"プ\", \"ペ\", \"ポ\", \"マ\", \"ミ\", \"ム\", \"メ\", \"モ\", \"ヤ\", \"ユ\", \"ヨ\", \"ラ\", \"リ\", \"ル\", \"レ\", \"ロ\", \"ワ\", \"ヲ\", \"ン\"];\n    return alphanumericarray;\n}\n\nfunction scr_ja_alphanumericarray_check(arg0 = \"ア\")\n{\n    var found = -4;\n    var _alphanumericarray = scr_ja_alphanumericarray();\n    \n    for (var i = 0; i < array_length(_alphanumericarray); i++)\n    {\n        if (arg0 == _alphanumericarray[i])\n        {\n            found = i;\n            break;\n        }\n    }\n    \n    return found;\n}\n",
    "scr_nameentrybadcheck": "function scr_nameentrybadcheck()\n{\n    var nextletter = false;\n    var lang = 0;\n    \n    if (global.lang == \"ja\")\n        lang = 1;\n    \n    if (lang == 0)\n    {\n        if (letter[0] == 5 && letter[1] == 20)\n        {\n            if (letter[2] == 2 || letter[2] == 10 || letter[2] == 16 || letter[2] == 23)\n                nextletter = true;\n        }\n        \n        if (letter[0] == 18 && letter[1] == 4 && letter[2] == 23)\n            nextletter = true;\n        \n        if (letter[0] == 2 && letter[1] == 20 && letter[2] == 12)\n            nextletter = true;\n        \n        if (letter[0] == 2 && letter[1] == 14)\n        {\n            if (letter[2] == 2 || letter[2] == 10 || letter[2] == 16)\n                nextletter = true;\n        }\n        \n        if (letter[0] == 5 && letter[1] == 2)\n        {\n            if (letter[2] == 10 || letter[2] == 23)\n                nextletter = true;\n        }\n        \n        if (letter[2] == 6)\n            nextletter = true;\n    }\n    else if (letter[2] == scr_ja_alphanumericarray_check(\"コ\") || letter[2] == scr_ja_alphanumericarray_check(\"ゲ\") || letter[2] == scr_ja_alphanumericarray_check(\"バ\") || letter[2] == scr_ja_alphanumericarray_check(\"ボ\") || letter[2] == scr_ja_alphanumericarray_check(\"ポ\"))\n    {\n        nextletter = true;\n    }\n    \n    return nextletter;\n}\n",
