    "ossafe_file_text_open_read": "function ossafe_file_text_open_read(arg0)\n{\n    if (!global.is_console)\n    {\n        return file_text_open_read(arg0);\n    }\n    else\n    {\n        var name = string_lower(arg0);\n        var file = ds_map_find_value(global.savedata, name);\n        \n        if (is_undefined(file))\n            return undefined;\n        \n        var data = file;\n        var num_lines = 0;\n        var lines;\n        \n        while (string_byte_length(data) > 0)\n        {\n            var newline_pos = string_pos(\"\\n\", data);\n            var line;\n            \n            if (newline_pos > 0)\n            {\n                var nextline_pos = newline_pos + 1;\n                \n                if (newline_pos > 1 && string_char_at(data, newline_pos - 1) == \"\\r\")\n                    newline_pos--;\n                \n                if (newline_pos > 1)\n                    line = substr(data, 1, newline_pos - 1);\n                else\n                    line = \"\";\n                \n                if (nextline_pos <= strlen(data))\n                    data = substr(data, nextline_pos);\n                else\n                    data = \"\";\n            }\n            else\n            {\n                line = data;\n                data = \"\";\n            }\n            \n            lines[num_lines++] = line;\n        }\n        \n        handle = ds_map_create();\n        ds_map_set(handle, \"is_write\", false);\n        ds_map_set(handle, \"text\", lines);\n        ds_map_set(handle, \"num_lines\", num_lines);\n        ds_map_set(handle, \"line\", 0);\n        ds_map_set(handle, \"line_read\", false);\n        return handle;\n    }\n}\n",
    "ossafe_file_text_read_string": "function ossafe_file_text_read_string(arg0)\n{\n    if (!global.is_console)\n    {\n        return file_text_read_string(arg0);\n    }\n    else\n    {\n        var handle = arg0;\n        \n        if (ds_map_find_value(handle, \"line_read\"))\n            return \"\";\n        \n        var line = ds_map_find_value(handle, \"line\");\n        \n        if (line >= ds_map_find_value(handle, \"num_lines\"))\n            return \"\";\n        \n        ds_map_set(handle, \"line_read\", true);\n        text = ds_map_find_value(handle, \"text\");\n        return text[line];\n    }\n}\n",
    "ossafe_file_text_readln": "function ossafe_file_text_readln(arg0)\n{\n    if (!global.is_console)\n    {\n        return file_text_readln(arg0);\n    }\n    else\n    {\n        var handle = arg0;\n        ds_map_set(handle, \"line_read\", false);\n        var line = ds_map_set_post(handle, \"line\", ds_map_find_value(handle, \"line\") + 1);\n        \n        if (line >= ds_map_find_value(handle, \"num_lines\"))\n            return \"\";\n        \n        text = ds_map_find_value(handle, \"text\");\n        return text[line] + \"\\r\\n\";\n    }\n}\n",
    "scr_ds_list_read": "function scr_ds_list_read(arg0)\n{\n    var new_list = ds_list_create();\n    var list_string = ossafe_file_text_read_string(arg0);\n    \n    if (list_string != \"\")\n        ds_list_read(new_list, list_string);\n    \n    return new_list;\n}\n",
    "ossafe_file_text_read_real": "function ossafe_file_text_read_real(arg0)\n{\n    if (!global.is_console)\n    {\n        return file_text_read_real(arg0);\n    }\n    else\n    {\n        var handle = arg0;\n        \n        if (ds_map_find_value(handle, \"line_read\"))\n            return 0;\n        \n        var line = ds_map_find_value(handle, \"line\");\n        \n        if (line >= ds_map_find_value(handle, \"num_lines\"))\n            return 0;\n        \n        ds_map_set(handle, \"line_read\", true);\n        text = ds_map_find_value(handle, \"text\");\n        return real(text[line]);\n    }\n}\n",
    "ossafe_file_text_close": "function ossafe_file_text_close(arg0)\n{\n    if (!global.is_console)\n    {\n        return file_text_close(arg0);\n    }\n    else\n    {\n        var handle = arg0;\n        \n        if (ds_map_find_value(handle, \"is_write\"))\n            ds_map_set(global.savedata, ds_map_find_value(handle, \"filename\"), ds_map_find_value(handle, \"data\"));\n        \n        ds_map_destroy(handle);\n    }\n}\n",
    "scr_dogcheck": "function scr_dogcheck()\n{\n    if (scr_debug())\n        return 0;\n    \n    var rooms = scr_get_room_list();\n    var dog_check = true;\n    \n    for (var i = 0; i < array_length_1d(rooms); i++)\n    {\n        if (rooms[i].room_id == global.currentroom)\n        {\n            dog_check = false;\n            break;\n        }\n    }\n    \n    return dog_check;\n}\n",
    "scr_emote": "function scr_emote()\n{\n    __dmult = 1 + global.darkzone;\n    __emotebubble = instance_create(x, y - 15, obj_excblcon);\n    __emotebubble.alarm[0] = argument[1];\n    __emotebubble.image_xscale = __dmult;\n    __emotebubble.image_yscale = __dmult;\n    __emotexoff = 0;\n    __emoteyoff = 0;\n    __anchorx = sprite_get_xoffset(sprite_index);\n    \n    if (argument[0] == \"!\")\n    {\n        __emotebubble.sprite_index = spr_exc;\n        __emotebubble.y = y - (10 * __dmult);\n        __emotexoff = 10 * __dmult;\n    }\n    \n    if (argument[0] == \"?\")\n    {\n        __emotebubble.sprite_index = spr_emote_questionmark;\n        __emotebubble.y = y - (10 * __dmult);\n        __emotexoff = 10 * __dmult;\n    }\n    \n    if (argument[0] == \"...\")\n    {\n        __emotebubble.sprite_index = spr_emote_ellipsis;\n        __emotebubble.y = y - (10 * __dmult);\n        __emotexoff = 10 * __dmult;\n    }\n    \n    if (argument[0] == \"note\")\n    {\n        __emotebubble.sprite_index = spr_musblc;\n        __emotebubble.y = y - (10 * __dmult);\n        __emotexoff = 10 * __dmult;\n    }\n    \n    if (argument_count >= 3)\n        __emotexoff = argument[2];\n    \n    if (argument_count >= 4)\n        __emoteyoff = argument[3];\n    \n    __emotebubble.y += __emoteyoff;\n    \n    if (image_xscale > 0)\n        __emotebubble.x = (((x - (__anchorx * image_xscale)) + ((sprite_width / 2) * sign(image_xscale))) - (__emotebubble.sprite_width / 2)) + __emotexoff;\n    else\n        __emotebubble.x = ((x + (__anchorx * image_xscale)) - ((sprite_width / 2) * sign(image_xscale)) - (__emotebubble.sprite_width / 2)) + __emotexoff;\n}\n",
    "scr_actor_facing": "function scr_actor_facing(arg0, arg1)\n{\n    __newfacing = arg1;\n    arg0.facing = __newfacing;\n    \n    if (__newfacing == \"d\")\n        arg0.sprite_index = arg0.dsprite;\n    \n    if (__newfacing == \"r\")\n        arg0.sprite_index = arg0.rsprite;\n    \n    if (__newfacing == \"l\")\n        arg0.sprite_index = arg0.lsprite;\n    \n    if (__newfacing == \"u\")\n        arg0.sprite_index = arg0.usprite;\n}\n",
    "scr_stickto_stop": "function scr_stickto_stop()\n{\n    if (variable_instance_exists(id, \"_stickto\"))\n    {\n        with (_stickto)\n            instance_destroy();\n    }\n}\n",
