    "scr_losechar": "function scr_losechar()\n{\n    global.char[2] = 0;\n    global.char[1] = 0;\n    \n    with (obj_darkcontroller)\n    {\n        chartotal = 0;\n        havechar[0] = 0;\n        havechar[1] = 0;\n        havechar[2] = 0;\n        havechar[3] = 0;\n        \n        for (i = 0; i < 3; i += 1)\n        {\n            global.faceaction[i] = 0;\n            \n            if (global.char[i] != 0)\n                chartotal += 1;\n            \n            if (global.char[i] == 1)\n            {\n                havechar[0] = 1;\n                charpos[0] = i;\n            }\n            \n            if (global.char[i] == 2)\n            {\n                havechar[1] = 1;\n                charpos[1] = i;\n            }\n            \n            if (global.char[i] == 3)\n            {\n                havechar[2] = 1;\n                charpos[2] = i;\n            }\n            \n            if (global.char[i] == 4)\n            {\n                havechar[3] = 1;\n                charpos[3] = i;\n            }\n        }\n    }\n    \n    global.submenu = 0;\n    global.charselect = -1;\n    \n    for (i = 0; i < 36; i += 1)\n        global.submenucoord[i] = 0;\n}\n",
    "scr_getchar": "function scr_getchar(arg0)\n{\n    switch (arg0)\n    {\n        case \"kr\":\n        case \"kris\":\n            arg0 = 1;\n            break;\n        \n        case \"su\":\n        case \"susie\":\n            arg0 = 2;\n            break;\n        \n        case \"ra\":\n        case \"ralsei\":\n            arg0 = 3;\n            break;\n        \n        case \"no\":\n        case \"noelle\":\n            arg0 = 4;\n            break;\n    }\n    \n    var characterToGet = arg0;\n    getchar = 0;\n    \n    if (global.char[0] == 0)\n    {\n        global.char[0] = characterToGet;\n        getchar = 1;\n    }\n    \n    if (global.char[1] == 0 && getchar == 0)\n    {\n        global.char[1] = characterToGet;\n        getchar = 1;\n    }\n    \n    if (global.char[2] == 0 && getchar == 0)\n    {\n        global.char[2] = characterToGet;\n        getchar = 1;\n    }\n    \n    with (obj_darkcontroller)\n    {\n        chartotal = 0;\n        havechar[0] = 0;\n        havechar[1] = 0;\n        havechar[2] = 0;\n        havechar[3] = 0;\n        \n        for (i = 0; i < 3; i += 1)\n        {\n            global.faceaction[i] = 0;\n            \n            if (global.char[i] != 0)\n                chartotal += 1;\n            \n            if (global.char[i] == 1)\n            {\n                havechar[0] = 1;\n                charpos[0] = i;\n            }\n            \n            if (global.char[i] == 2)\n            {\n                havechar[1] = 1;\n                charpos[1] = i;\n            }\n            \n            if (global.char[i] == 3)\n            {\n                havechar[2] = 1;\n                charpos[2] = i;\n            }\n            \n            if (global.char[i] == 4)\n            {\n                havechar[3] = 1;\n                charpos[3] = i;\n            }\n        }\n    }\n}\n",
