    "scr_debug_keycheck": "function scr_debug_keycheck(arg0)\n{\n}\n",
    "scr_fadeout": "function scr_fadeout(arg0)\n{\n    __fadeouter = instance_create(camerax() - 200, cameray() - 200, obj_fadeout);\n    __fadeouter.fadespeed = 1 / arg0;\n    __fadeouter.depth = 3;\n    return __fadeouter;\n}\n",
    "mus_fade": "function mus_fade(arg0, arg1)\n{\n    audio_sound_gain(arg0, 0, (arg1 * 1000) / fps);\n}\n",
    "scr_mnendturn": "function scr_mnendturn()\n{\n    if (global.char[0] == 2)\n        sus = 0;\n    \n    if (global.char[1] == 2)\n        sus = 1;\n    \n    if (global.char[2] == 2)\n        sus = 2;\n    \n    techwon = 0;\n    \n    if (scr_monsterpop() == 0)\n        techwon = 1;\n    \n    if (global.flag[39] == 1)\n        techwon = 1;\n    \n    if (techwon == 1)\n        scr_wincombat();\n    \n    if (techwon == 0)\n    {\n        with (obj_battlecontroller)\n        {\n            messagepriority = -1;\n            attackpriority = -1;\n        }\n        \n        scr_battlecursor_memory_reset();\n        global.mnfight = 0;\n        global.myfight = 0;\n        global.bmenuno = 0;\n        global.charturn = 0;\n        skip = 0;\n        \n        for (i = 0; i < 3; i += 1)\n        {\n            global.hittarget[i] = 0;\n            \n            with (global.charinstance[i])\n                tu = 0;\n            \n            hptarget = global.char[i];\n            \n            if (global.chapter == 4 && i_ex(obj_titan_enemy) && obj_titan_enemy.gerson.sprite_index == spr_gerson_item)\n                continue;\n            \n            if (global.char[i] != 0 && global.hp[hptarget] <= 0)\n            {\n                healamt = ceil(global.maxhp[hptarget] / 8);\n                dmgwr = instance_create(global.charinstance[i].x, (global.charinstance[i].y + global.charinstance[i].myheight) - 24, obj_dmgwriter);\n                \n                with (dmgwr)\n                {\n                    delay = 1;\n                    type = 3;\n                }\n                \n                dmgwr.damage = scr_heal(i, healamt);\n                \n                if (global.hp[hptarget] >= 1)\n                {\n                    with (dmgwr)\n                        specialmessage = 4;\n                }\n            }\n        }\n        \n        if (global.charmove[0] == 0 || global.charauto[global.char[0]] == 1)\n            global.charturn = 1;\n        \n        if (global.charturn == 1)\n        {\n            if (global.charmove[1] == 0 || global.charauto[global.char[1]] == 1)\n                global.charturn = 2;\n        }\n        \n        if (global.charturn == 2)\n        {\n            if (global.charmove[2] == 0 || global.charauto[global.char[2]] == 1)\n                skip = 1;\n        }\n        \n        for (i = 0; i < 3; i += 1)\n        {\n            global.acting[i] = 0;\n            global.actingsingle[i] = 0;\n            global.actingsimul[i] = 0;\n            global.actingtarget[i] = 0;\n            global.temptension[i] = global.tension;\n            global.charspecial[i] = 0;\n            global.targeted[i] = 0;\n            global.charaction[i] = 0;\n            global.faceaction[i] = 0;\n            global.monsterattackname[i] = \" \";\n        }\n        \n        global.currentactingchar = 0;\n        \n        with (obj_monsterparent)\n        {\n            attacked = 0;\n            talked = 0;\n            acting = 0;\n            actingsus = 0;\n            actingral = 0;\n            actingnoe = 0;\n        }\n        \n        if (skip == 1)\n        {\n            if (global.char[0] == 2 && global.charauto[2] == 1)\n            {\n                global.acting[0] = 1;\n                global.myfight = 3;\n            }\n            \n            scr_endturn();\n        }\n        \n        if (disablesusieattack == 1 && global.charturn == 1)\n            global.bmenucoord[0][global.charturn] = 1;\n        \n        for (i = 0; i < 12; i += 1)\n        {\n            for (j = 0; j < 3; j += 1)\n                tempitem[i][j] = global.item[i];\n        }\n    }\n}\n",
    "snd_loop": "function snd_loop(arg0)\n{\n    return audio_play_sound(arg0, 50, 1);\n}\n\nfunction sound_loop(arg0)\n{\n    snd_loop(arg0);\n}\n",
