    "draw_monster_body_part_ext": "function draw_monster_body_part_ext(arg0, arg1, arg2, arg3, arg4, arg5, arg6, arg7, arg8)\n{\n    draw_sprite_ext(arg0, arg1, arg2, arg3, arg4, arg5, arg6, arg7, arg8);\n    \n    if (flash == 1)\n        draw_sprite_ext_flash(arg0, arg1, arg2, arg3, arg4, arg5, arg6, arg7, (-cos(fsiner / 5) * 0.4) + 0.6);\n}\n",
    "scr_attackpriority": "function scr_attackpriority(arg0)\n{\n    if (i_ex(obj_battlecontroller))\n    {\n        if (obj_battlecontroller.attackpriority < arg0)\n        {\n            obj_battlecontroller.attackpriority = arg0;\n            return true;\n        }\n        else\n        {\n            return false;\n        }\n    }\n    else\n    {\n        return false;\n    }\n}\n",
    "scr_blconskip": "function scr_blconskip(arg0)\n{\n    if (arg0 >= 0)\n    {\n        if (button1_p() && talktimer > arg0)\n            talktimer = talkmax;\n        \n        talktimer += 1;\n        \n        if (talktimer >= talkmax)\n        {\n            with (obj_writer)\n                instance_destroy();\n            \n            with (obj_guei_balloon)\n                instance_destroy();\n            \n            global.mnfight = 1.5;\n        }\n    }\n    else if (arg0 == -1)\n    {\n        if (instance_exists(obj_writer) == false)\n            global.mnfight = 1.5;\n    }\n    else if (arg0 == -2)\n    {\n        talktimer += 1;\n        \n        if (talktimer > 15)\n            talktimer = talkmax;\n        \n        if (talktimer >= talkmax)\n        {\n            with (obj_writer)\n                instance_destroy();\n            \n            with (obj_guei_balloon)\n                instance_destroy();\n            \n            global.mnfight = 1.5;\n        }\n    }\n}\n",
    "scr_bulletspawner": "function scr_bulletspawner(arg0, arg1, arg2)\n{\n    __dc = instance_create(arg0, arg1, arg2);\n    __dc.creator = myself;\n    __dc.creatorid = id;\n    __dc.target = mytarget;\n    __dc.damage = global.monsterat[myself] * 5;\n    return __dc;\n}\n",
    "scr_messagepriority": "function scr_messagepriority(arg0)\n{\n    if (i_ex(obj_battlecontroller))\n    {\n        if (obj_battlecontroller.messagepriority < arg0)\n        {\n            obj_battlecontroller.messagepriority = arg0;\n            return true;\n        }\n        else\n        {\n            return false;\n        }\n    }\n    else\n    {\n        return false;\n    }\n}\n",
    "scr_monster_make_tired": "function scr_monster_make_tired(arg0)\n{\n    if (global.monsterstatus[arg0] == 0)\n    {\n        __tiredwriter = instance_create(global.monsterx[arg0], (global.monstery[arg0] - (global.hittarget[arg0] * 20)) + 20, obj_dmgwriter);\n        __tiredwriter.type = 13;\n        global.hittarget[arg0] += 1;\n        snd_play_x(snd_spellcast, 0.5, 0.9);\n    }\n    \n    global.monstercomment[arg0] = stringsetloc(\"(Tired)\", \"scr_monster_make_tired_slash_scr_monster_make_tired_gml_1_0\");\n    global.monsterstatus[arg0] = 1;\n}\n",
    "scr_battletext_default": "function scr_battletext_default()\n{\n    global.fc = 0;\n    global.typer = 4;\n    scr_battletext();\n    return battlewriter;\n}\n",
    "scr_mercyadd": "function scr_mercyadd(arg0, arg1)\n{\n    global.mercymod[arg0] += arg1;\n    \n    if (global.mercymod[arg0] < 0)\n        global.mercymod[arg0] = 0;\n    \n    if (global.mercymod[arg0] >= 100)\n        global.mercymod[arg0] = 100;\n    \n    var _playsound = 1;\n    \n    if (arg1 <= 0)\n        _playsound = 0;\n    \n    with (obj_dmgwriter)\n    {\n        if (type == 5 && mercytimer < 8)\n            _playsound = 0;\n    }\n    \n    if (_playsound)\n    {\n        var _pitch = 0.8;\n        \n        if (arg1 < 99)\n            _pitch = 1;\n        \n        if (arg1 <= 50)\n            _pitch = 1.2;\n        \n        if (arg1 <= 25)\n            _pitch = 1.4;\n        \n        snd_play_x(snd_mercyadd, 0.8, _pitch);\n    }\n    \n    __mercydmgwriter = instance_create(global.monsterx[arg0], (global.monstery[arg0] + 20) - (global.hittarget[arg0] * 20), obj_dmgwriter);\n    __mercydmgwriter.damage = arg1;\n    __mercydmgwriter.type = 5;\n    global.hittarget[arg0]++;\n}\n",
    "scr_simultext": "function scr_simultext(arg0)\n{\n    __simulorder = 0;\n    \n    if (arg0 == \"kris\")\n        __simulorder = simulorderkri;\n    \n    if (arg0 == \"susie\")\n        __simulorder = simulordersus;\n    \n    if (arg0 == \"ralsei\")\n        __simulorder = simulorderral;\n    \n    if (arg0 == \"noelle\")\n        __simulorder = simulordernoe;\n    \n    __yoffset = __simulorder * 30;\n    global.typer = 4;\n    battlewriter = instance_create(xx + 30, yy + 376 + __yoffset, obj_writer);\n}\n",
    "scr_enemyhurt_tired_after_damage": "function scr_enemyhurt_tired_after_damage(arg0)\n{\n    if (global.monsterhp[myself] <= (global.monstermaxhp[myself] * arg0))\n        scr_monster_make_tired(myself);\n}\n",
    "snd_is_playing": "function snd_is_playing(arg0)\n{\n    return audio_is_playing(arg0);\n}\n\nfunction sound_is_playing(arg0)\n{\n    snd_is_playing(arg0);\n}\n",
