    "scr_shop_vending": "function scr_shop_vending()\n{\n}\n\nfunction vending_menu_option(arg0 = \"\", arg1 = 0, arg2 = \"\", arg3 = 0) constructor\n{\n    option_text = arg0;\n    menu_type = arg1;\n    talk_flag = arg2;\n    talk_style = arg3;\n    times_selected = 0;\n}\n\nfunction vending_item(arg0 = 0, arg1 = \"\", arg2 = 0) constructor\n{\n    item_id = arg0;\n    item_type = arg1;\n    item_desc = vending_get_item_description(item_id, item_type);\n    point_value = arg2;\n}\n\nfunction vending_event(arg0 = 0, arg1 = \"\", arg2 = 0, arg3 = \"\", arg4 = []) constructor\n{\n    item_id = arg0;\n    item_type = \"event\";\n    item_desc = arg1;\n    point_value = arg2;\n    price_label = arg3;\n    sold_flag = arg4;\n}\n\nfunction vending_get_item_description(arg0 = 0, arg1 = \"\")\n{\n    var _desc = \"\";\n    \n    if (arg1 == \"item\")\n    {\n        switch (arg0)\n        {\n            case 61:\n                _desc = stringsetloc(\"ITEM#Tea made#of chants,#heals 115HP\", \"scr_shop_vending_slash_scr_shop_vending_gml_43_0_b\");\n                break;\n            \n            case 62:\n                _desc = stringsetloc(\"ITEM#Sick#juice that#heals 160HP\", \"scr_shop_vending_slash_scr_shop_vending_gml_46_0_b\");\n                break;\n            \n            default:\n                break;\n        }\n    }\n    else if (arg1 == \"armor\")\n    {\n        switch (arg0)\n        {\n            case 50:\n                _desc = stringsetloc(\"ARMOR#Holey#amulet\", \"scr_shop_vending_slash_scr_shop_vending_gml_56_0\");\n                break;\n            \n            default:\n                break;\n        }\n    }\n    else if (arg1 == \"weapon\")\n    {\n        switch (arg0)\n        {\n            case 51:\n                _desc = stringsetloc(\"WEAPON#Pagekeeper#scarf DF+1\", \"scr_shop_vending_slash_scr_shop_vending_gml_66_0_b\");\n                break;\n            \n            default:\n                break;\n        }\n    }\n    \n    return _desc;\n}\n",
    "snd_init": "function snd_init(arg0)\n{\n    var dir = \"mus/\";\n    \n    if (global.launcher)\n        dir = working_directory + \"../mus/\";\n    \n    initsongvar = dir + arg0;\n    _mystream = audio_create_stream(initsongvar);\n    _astream = instance_create(0, 0, obj_astream);\n    _astream.mystream = _mystream;\n    _astream.songname = arg0;\n    return _mystream;\n}\n\nfunction sound_init(arg0)\n{\n    snd_init(arg0);\n}\n",
    "mus_loop": "function mus_loop(arg0)\n{\n    _xsndinstance = audio_play_sound(arg0, 90, 1);\n    snd_volume(_xsndinstance, 1 * global.flag[16], 0);\n    return _xsndinstance;\n}\n",
    "snd_free": "function snd_free(arg0)\n{\n    if (instance_exists(obj_astream))\n    {\n        _xstream = arg0;\n        obj_astream.bstream = _xstream;\n        \n        with (obj_astream)\n        {\n            if (bstream == mystream)\n                instance_destroy();\n        }\n    }\n}\n\nfunction sound_free(arg0)\n{\n    snd_free(arg0);\n}\n",
