    "scr_spellconsumeb": "function scr_spellconsumeb()\n{\n    global.tension -= floor(floor((cost / global.maxtension) * 100) * 2.5);\n    global.faceaction[global.charturn] = 2;\n    global.charaction[global.charturn] = 2;\n    \n    if (global.flag[34] == 1)\n        global.charspecial[global.charturn] = global.spell[global.char[global.charturn]][global.bmenucoord[2][global.charturn]];\n    \n    if (global.flag[34] == 0)\n        global.charspecial[global.charturn] = global.battlespell[global.charturn][global.bmenucoord[2][global.charturn]];\n    \n    global.tensionselect = 0;\n    \n    if (spellanim == 1)\n    {\n        with (global.charinstance[global.charturn])\n        {\n            spellframes = 0;\n            spellsprite = spellreadysprite;\n        }\n    }\n    else\n    {\n        with (global.charinstance[global.charturn])\n        {\n            spellframes = remspellframes;\n            spellsprite = remspellsprite;\n        }\n    }\n    \n    scr_nexthero();\n}\n",
    "scr_nexthero": "function scr_nexthero()\n{\n    moveswapped = 0;\n    prevturn = global.charturn;\n    \n    if (global.charturn == 0)\n    {\n        moveswapped = 1;\n        \n        if ((global.charmove[1] == 1 && scr_charcan(1) && obj_battlecontroller.skipsusieturn == false) || (i_ex(obj_sound_of_justice_enemy) && i_ex(obj_herokris)))\n            global.charturn = 1;\n        else if (global.charmove[2] == 1 && scr_charcan(2))\n            global.charturn = 2;\n        else\n            scr_endturn();\n    }\n    \n    if (global.charturn == 1 && moveswapped == 0)\n    {\n        moveswapped = 1;\n        \n        if (scr_charcan(2) && global.acting[1] == 0)\n            global.charturn = 2;\n        else\n            scr_endturn();\n    }\n    \n    if (global.charturn == 2 && moveswapped == 0)\n        scr_endturn();\n    \n    if (moveswapped == 1)\n        global.bmenuno = 0;\n    \n    if (global.charturn > 0)\n    {\n        global.temptension[global.charturn] = global.tension;\n        \n        for (i = 0; i < 12; i += 1)\n            tempitem[i][global.charturn] = tempitem[i][prevturn];\n    }\n    \n    if (disablesusieattack == 1 && global.charturn == 1)\n        global.bmenucoord[0][global.charturn] = 1;\n}\n",
    "scr_armorcheck_equipped_party": "function scr_armorcheck_equipped_party(arg0)\n{\n    var __totalwearing = 0;\n    \n    for (var __weari = 0; __weari < 3; __weari++)\n    {\n        if (global.char[__weari] != 0)\n            __totalwearing += scr_armorcheck_equipped(global.char[__weari], arg0);\n    }\n    \n    return __totalwearing;\n}\n",
    "scr_levelup": "function scr_levelup()\n{\n    var krismaxhp = 240;\n    var susiemaxhp = 290;\n    var ralseimaxhp = 210;\n    var encountercountflag = 1580;\n    var attackpluscountflag = 1618;\n    var gainedstats = 0;\n    global.flag[encountercountflag]++;\n    \n    if (global.maxhp[1] < krismaxhp || global.maxhp[2] < susiemaxhp || global.maxhp[3] < ralseimaxhp)\n    {\n        gainedstats = 1;\n        \n        if (global.maxhp[1] < krismaxhp)\n        {\n            global.maxhp[1] += 2;\n            global.hp[1] += 2;\n        }\n        \n        if (global.maxhp[2] < susiemaxhp)\n        {\n            global.maxhp[2] += 2;\n            global.hp[2] += 2;\n        }\n        \n        if (global.maxhp[3] < ralseimaxhp)\n        {\n            global.maxhp[3] += 2;\n            global.hp[3] += 2;\n        }\n        \n        if ((global.flag[encountercountflag] % 2) == 0)\n            global.maxhp[2] += 1;\n    }\n    \n    if ((global.flag[encountercountflag] % 10) == 0 && global.flag[attackpluscountflag] < 2)\n    {\n        gainedstats = 1;\n        global.at[1] += 1;\n        global.at[2] += 1;\n        global.mag[2] += 1;\n        global.at[3] += 1;\n        global.mag[3] += 1;\n        global.flag[attackpluscountflag]++;\n    }\n    \n    if (scr_havechar(4))\n    {\n        global.flag[919]++;\n        global.maxhp[4] += 4;\n        global.hp[4] += 4;\n        \n        if ((global.flag[1580] % 4) == 0)\n        {\n            global.at[4] += 1;\n            global.mag[4] += 1;\n        }\n    }\n    \n    global.maxhp[1] = clamp(global.maxhp[1], 10, krismaxhp);\n    global.maxhp[2] = clamp(global.maxhp[2], 10, susiemaxhp);\n    global.maxhp[3] = clamp(global.maxhp[3], 10, ralseimaxhp);\n    global.maxhp[4] = clamp(global.maxhp[4], 10, 999);\n    \n    for (var _i = 1; _i < 5; _i++)\n        global.hp[_i] = min(global.hp[_i], global.maxhp[_i]);\n    \n    return gainedstats;\n}\n",
    "scr_battletext": "function scr_battletext()\n{\n    xx = __view_get(e__VW.XView, 0);\n    yy = __view_get(e__VW.YView, 0);\n    \n    if (global.fc != 0)\n        battlewriter = instance_create(xx + 30, yy + 376, obj_writer);\n    \n    if (global.fc == 0)\n        battlewriter = instance_create(xx + 30, yy + 376, obj_writer);\n    \n    myface = instance_create(xx + 26, yy + 380, obj_face);\n    \n    with (battlewriter)\n    {\n        dialoguer = 1;\n        facer = 1;\n        \n        if (global.fc == 0 && originalcharline == 33)\n            charline = 26;\n    }\n    \n    return battlewriter;\n}\n\nenum e__VW\n{\n    XView,\n    YView,\n    WView,\n    HView,\n    Angle,\n    HBorder,\n    VBorder,\n    HSpeed,\n    VSpeed,\n    Object,\n    Visible,\n    XPort,\n    YPort,\n    WPort,\n    HPort,\n    Camera,\n    SurfaceID\n}\n",
    "scr_endcombat": "function scr_endcombat()\n{\n    global.fighting = 0;\n    \n    if (global.specialbattle == 0 || global.specialbattle == 2 || global.specialbattle == 3)\n    {\n        if (global.specialbattle == 2)\n        {\n            with (obj_mainchara)\n            {\n                cutscene = 1;\n                x = global.charinstance[0].x;\n                y = global.charinstance[0].y;\n            }\n            \n            with (global.cinstance[0])\n            {\n                x = global.charinstance[1].x;\n                y = global.charinstance[1].y;\n            }\n            \n            with (global.cinstance[1])\n            {\n                x = global.charinstance[2].x;\n                y = global.charinstance[2].y;\n            }\n            \n            with (obj_caterpillarchara)\n                scr_caterpillar_interpolate();\n            \n            scr_pan_to_obj(obj_mainchara, 30);\n            \n            with (obj_mainchara)\n                visible = 1;\n            \n            with (obj_caterpillarchara)\n                visible = 1;\n        }\n        \n        instance_create(0, 0, obj_endbattle);\n        \n        with (obj_monsterparent)\n            instance_destroy();\n        \n        with (obj_bulletparent)\n            instance_destroy();\n        \n        with (obj_heroparent)\n            instance_destroy();\n        \n        global.charinstance[0] = obj_mainchara;\n        global.charinstance[1] = global.cinstance[0];\n        global.charinstance[2] = global.cinstance[1];\n        instance_destroy();\n    }\n}\n",
