    "scr_itemshift": "function scr_itemshift(arg0, arg1)\n{\n    global.item[12] = arg1;\n    \n    for (i = arg0; i < 12; i += 1)\n        global.item[i] = global.item[i + 1];\n    \n    scr_iteminfo_all();\n    scr_itemname();\n}\n",
    "scr_itemdesc": "function scr_itemdesc()\n{\n    for (i = 0; i < 12; i += 1)\n    {\n        itemid = global.item[i];\n        itemdesc[i] = scr_itemdesc_single(itemid);\n    }\n}\n",
    "scr_spell_overworld": "function scr_spell_overworld(arg0)\n{\n    w = arg0;\n    usable = 0;\n    \n    switch (arg0)\n    {\n        case 0:\n            break;\n        \n        case 2:\n            scr_healitem(global.charselect, 100);\n            break;\n    }\n}\n",
