    "c_msgsetloc": "function c_msgsetloc(arg0, arg1, arg2)\n{\n    var msg_index = arg0;\n    var english = arg1;\n    var localized_string_id = arg2;\n    var str = english;\n    \n    if (!is_english())\n        str = scr_84_get_lang_string(localized_string_id);\n    \n    c_msgset(msg_index, str);\n}\n",
    "c_talk_wait": "function c_talk_wait()\n{\n    c_talk();\n    c_waittalk();\n}\n\nfunction c_talkwait()\n{\n    c_talk_wait();\n}\n",
