    "draw_circle_pie": "function draw_circle_pie(arg0, arg1, arg2, arg3, arg4, arg5, arg6)\n{\n    if (arg2 > 0)\n    {\n        var numofsections = 60;\n        var sizeofsection = 360 / numofsections;\n        var val = (arg2 / arg3) * numofsections;\n        \n        if (val > 1)\n        {\n            draw_set_colour(arg4);\n            draw_set_alpha(arg6);\n            draw_primitive_begin(pr_trianglefan);\n            draw_vertex(arg0, arg1);\n            \n            for (var i = 0; i <= val; i++)\n            {\n                var len = (i * sizeofsection) + 90;\n                var tx = lengthdir_x(arg5, len);\n                var ty = lengthdir_y(arg5, len);\n                draw_vertex(arg0 + tx, arg1 + ty);\n            }\n            \n            draw_primitive_end();\n        }\n        \n        draw_set_alpha(1);\n    }\n}\n",
    "scr_healallitemspell": "function scr_healallitemspell(arg0)\n{\n    var __healAmount = arg0;\n    scr_healall(__healAmount);\n    \n    for (i = 0; i < 3; i += 1)\n    {\n        with (global.charinstance[i])\n        {\n            ha = instance_create(x, y, obj_healanim);\n            ha.target = id;\n            dmgwr = scr_dmgwriter_selfchar();\n            \n            with (dmgwr)\n            {\n                delay = 8;\n                type = 3;\n                damage = arg0;\n            }\n            \n            if (global.hp[global.char[myself]] >= global.maxhp[global.char[myself]])\n            {\n                with (dmgwr)\n                    specialmessage = 3;\n            }\n            \n            tu += 1;\n        }\n    }\n    \n    global.spelldelay = 20;\n}\n",
    "scr_create_hitbox_solid": "function scr_create_hitbox_solid()\n{\n    var _hitboxwidth = bbox_right - bbox_left;\n    var _hitboxheight = bbox_bottom - bbox_top;\n    ___createdsolid = instance_create(bbox_left, bbox_top, obj_soliddark);\n    ___createdsolid.image_xscale = 0.025 * _hitboxwidth;\n    ___createdsolid.image_yscale = 0.025 * _hitboxheight;\n    return ___createdsolid;\n}\n",
