    "scr_calculate_move_distance": "function scr_calculate_move_distance(arg0, arg1, arg2, arg3, arg4 = 6)\n{\n    var move_time = 1;\n    var distance_time = round(point_distance(arg0, arg1, arg2, arg3) / arg4);\n    \n    if (distance_time > move_time)\n        move_time = distance_time;\n    \n    return move_time;\n}\n",
