    "draw_text_kern": "function draw_text_kern(arg0, arg1, arg2, arg3)\n{\n    var tx = argument[0];\n    var ty = argument[1];\n    var txt = argument[2];\n    var kern = argument[3];\n    var tox = tx;\n    \n    for (var i = 1; i <= string_length(arg2); i += 1)\n    {\n        var ch = string_char_at(txt, i);\n        \n        if (ch == \"\\n\" || ch == \"#\")\n        {\n            ty += string_height(\"|\");\n            tx = tox;\n        }\n        else\n        {\n            draw_text(tx, ty, ch);\n            tx += string_width(ch);\n            tx += kern;\n        }\n    }\n}\n\nfunction draw_text_kern_legend(arg0, arg1, arg2, arg3)\n{\n    var tx = argument[0];\n    var ty = argument[1];\n    var txt = argument[2];\n    var kern = argument[3];\n    var tox = tx;\n    \n    for (var i = 1; i <= string_length(arg2); i += 1)\n    {\n        var ch = string_char_at(txt, i);\n        \n        if (ch == \"\\n\" || ch == \"#\")\n        {\n            ty += string_height(\"|\");\n            tx = tox;\n        }\n        else\n        {\n            var x_offset = 0;\n            \n            if (ch == \"L\")\n                x_offset = 1;\n            \n            draw_text(tx + x_offset, ty, ch);\n            tx += string_width(ch);\n            tx += kern;\n        }\n    }\n}\n",
    "scr_damage_cache": "function scr_damage_cache()\n{\n    global.damage_cache = [];\n    \n    for (var i = 0; i < 3; i++)\n        global.damage_cache[array_length(global.damage_cache)] = global.hp[global.char[i]];\n}\n\nfunction scr_damage_check()\n{\n    if (!variable_global_exists(\"damage_cache\"))\n        global.damage_cache = [];\n    \n    var took_damage = false;\n    \n    for (var i = 0; i < array_length(global.damage_cache); i++)\n    {\n        var hp_cache = global.damage_cache[i];\n        \n        if (global.hp[global.char[i]] < hp_cache)\n        {\n            took_damage = true;\n            break;\n        }\n    }\n    \n    if (took_damage)\n    {\n        with (obj_event_manager)\n            trigger_event(UnknownEnum.Value_1);\n    }\n}\n\nenum UnknownEnum\n{\n    Value_1 = 1\n}\n",
