    "scr_get_input_name_console": "function scr_get_input_name_console(arg0)\n{\n    var _control = arg0;\n    var _input_name = \"?\";\n    \n    switch (_control)\n    {\n        case gp_padr:\n            _input_name = \"\\\\*D  \";\n            break;\n        \n        case gp_padl:\n            _input_name = \"\\\\*A  \";\n            break;\n        \n        case gp_padu:\n            _input_name = \"\\\\*W  \";\n            break;\n        \n        case gp_padd:\n            _input_name = \"\\\\*S  \";\n            break;\n        \n        case global.button0:\n            _input_name = \"\\\\*Z  \";\n            break;\n        \n        case global.button1:\n            _input_name = \"\\\\*X  \";\n            break;\n        \n        case global.button2:\n            _input_name = \"\\\\*C  \";\n            break;\n        \n        case gp_shoulderl:\n            _input_name = \"\\\\*l  \";\n            break;\n        \n        case gp_shoulderlb:\n            _input_name = \"\\\\*L  \";\n            break;\n        \n        case gp_shoulderr:\n            _input_name = \"\\\\*r  \";\n            break;\n        \n        case gp_shoulderrb:\n            _input_name = \"\\\\*R  \";\n            break;\n        \n        case gp_stickl:\n            _input_name = \"\\\\*j  \";\n            break;\n        \n        case gp_stickr:\n            _input_name = \"\\\\*J  \";\n            break;\n    }\n    \n    return _input_name;\n}\n",
