    "scr_damage_all": "function scr_damage_all()\n{\n    if (global.inv < 0)\n    {\n        scr_damage_cache();\n        remdamage = damage;\n        _temptarget = target;\n        \n        for (ti = 0; ti < 3; ti += 1)\n        {\n            global.inv = -1;\n            damage = remdamage;\n            target = ti;\n            \n            if (global.hp[global.char[ti]] > 0 && global.char[ti] != 0)\n                scr_damage();\n        }\n        \n        global.inv = global.invc * 40;\n        target = _temptarget;\n        scr_damage_check();\n    }\n}\n",
    "scr_healitemspell": "function scr_healitemspell(arg0)\n{\n    scr_heal(star, arg0);\n    global.spelldelay = 15;\n    \n    with (global.charinstance[star])\n    {\n        ha = instance_create(x, y, obj_healanim);\n        ha.target = id;\n        \n        if (global.chapter == 2 && instance_exists(o_boxingcontroller))\n            ha.target = o_boxingcontroller.id;\n        \n        dmgwr = scr_dmgwriter_selfchar();\n        \n        with (dmgwr)\n        {\n            delay = 8;\n            type = 3;\n            damage = arg0;\n        }\n        \n        if (global.hp[global.char[myself]] >= global.maxhp[global.char[myself]])\n        {\n            with (dmgwr)\n                specialmessage = 3;\n        }\n        \n        tu += 1;\n        return ha;\n    }\n}\n",
