    "scr_blconskip": "function scr_blconskip(arg0)\n{\n    if (arg0 >= 0)\n    {\n        if (button1_p() && talktimer > arg0)\n            talktimer = talkmax;\n        \n        talktimer += 1;\n        \n        if (talktimer >= talkmax)\n        {\n            with (obj_writer)\n                instance_destroy();\n            \n            global.mnfight = 2;\n        }\n    }\n    else if (arg0 == -1)\n    {\n        if (instance_exists(obj_writer) == false)\n            global.mnfight = 2;\n    }\n    else if (arg0 == -2)\n    {\n        talktimer += 1;\n        \n        if (talktimer > 15)\n            talktimer = talkmax;\n        \n        if (talktimer >= talkmax)\n        {\n            with (obj_writer)\n                instance_destroy();\n            \n            global.mnfight = 2;\n        }\n    }\n}\n",
