    "scr_sideb_fail": "function scr_sideb_fail()\n{\n    if (global.flag[916] == 0)\n    {\n        global.flag[916] = 1;\n        \n        if (argument_count > 0 && argument[0] == 1)\n        {\n            if (global.flag[915] > 0)\n            {\n            }\n        }\n    }\n}\n",
    "scr_prioritytarget": "function scr_prioritytarget(arg0, arg1, arg2)\n{\n    abletotarget = 1;\n    \n    if (global.charcantarget[0] == 0 && global.charcantarget[1] == 0 && global.charcantarget[2] == 0)\n        abletotarget = 0;\n    \n    mytarget = scr_weightedrandom(arg0, arg1, arg2);\n    \n    if (abletotarget == 1)\n    {\n        while (global.charcantarget[mytarget] == 0)\n            mytarget = scr_weightedrandom(arg0, arg1, arg2);\n    }\n    else\n    {\n        mytarget = 3;\n    }\n    \n    global.targeted[mytarget] = 1;\n    \n    if (global.chapter >= 2 && mytarget != 3)\n    {\n        if (global.charcantarget[0])\n            global.targeted[0] = 1;\n        \n        if (global.charcantarget[1])\n            global.targeted[1] = 1;\n        \n        if (global.charcantarget[2])\n            global.targeted[2] = 1;\n        \n        mytarget = 4;\n    }\n}\n",
    "scr_monster_add": "function scr_monster_add(arg0, arg1)\n{\n    __returnid = -1;\n    \n    for (__mopenslot = 0; __mopenslot < 3; __mopenslot++)\n    {\n        if (global.monster[__mopenslot] == 0)\n        {\n            global.monstertype[__mopenslot] = arg0;\n            global.monsterinstancetype[__mopenslot] = arg1;\n            scr_monster_statreset(__mopenslot);\n            scr_monster_makeinstance(__mopenslot);\n            __returnid = __mopenslot;\n            break;\n        }\n    }\n    \n    return __returnid;\n}\n",
    "stringset": "function stringset(arg0)\n{\n    return arg0;\n}\n",
    "scr_flip": "function scr_flip(arg0)\n{\n    if (arg0 == \"h\" || arg0 == \"x\")\n    {\n        x += ((sprite_get_width(sprite_index) - (sprite_get_xoffset(sprite_index) * 2)) * image_xscale);\n        image_xscale = -image_xscale;\n    }\n    else\n    {\n        y += ((sprite_get_height(sprite_index) - (sprite_get_yoffset(sprite_index) * 2)) * image_yscale);\n        image_yscale = -image_yscale;\n    }\n}\n",
    "scr_losechar": "function scr_losechar()\n{\n    global.char[2] = 0;\n    global.char[1] = 0;\n    \n    with (obj_darkcontroller)\n    {\n        chartotal = 0;\n        havechar[0] = 0;\n        havechar[1] = 0;\n        havechar[2] = 0;\n        havechar[3] = 0;\n        \n        for (i = 0; i < 3; i += 1)\n        {\n            global.faceaction[i] = 0;\n            \n            if (global.char[i] != 0)\n                chartotal += 1;\n            \n            if (global.char[i] == 1)\n            {\n                havechar[0] = 1;\n                charpos[0] = i;\n            }\n            \n            if (global.char[i] == 2)\n            {\n                havechar[1] = 1;\n                charpos[1] = i;\n            }\n            \n            if (global.char[i] == 3)\n            {\n                havechar[2] = 1;\n                charpos[2] = i;\n            }\n            \n            if (global.char[i] == 4)\n            {\n                havechar[3] = 1;\n                charpos[3] = i;\n            }\n        }\n    }\n    \n    global.submenu = 0;\n    global.charselect = -1;\n    \n    for (i = 0; i < 36; i += 1)\n        global.submenucoord[i] = 0;\n}\n",
    "scr_shakeobj": "function scr_shakeobj()\n{\n    shakeobj = instance_create(x, y, obj_shakeobj);\n    shakeobj.target = id;\n    \n    with (shakeobj)\n        event_user(0);\n}\n",
    "scr_spare": "function scr_spare(arg0)\n{\n    with (global.monsterinstance[arg0])\n        event_user(10);\n}\n",
    "scr_monster_change": "function scr_monster_change(arg0, arg1, arg2)\n{\n    global.monstertype[arg0] = arg1;\n    global.monsterinstancetype[arg0] = arg2;\n    scr_monster_statreset(arg0);\n    scr_monster_makeinstance(arg0);\n}\n",
    "draw_background_tiled_ext": "function draw_background_tiled_ext(arg0, arg1, arg2, arg3, arg4, arg5, arg6)\n{\n    draw_sprite_tiled_ext(arg0, 0, arg1, arg2, arg3, arg4, arg5, arg6);\n}\n",
    "d_ex": "function d_ex()\n{\n    return instance_exists(obj_dialoguer);\n}\n",
    "lerp_ease_inout": "function lerp_ease_inout(arg0, arg1, arg2, arg3)\n{\n    return lerp(arg0, arg1, scr_ease_inout(arg2, arg3));\n}\n",
    "scr_dbox": "function scr_dbox()\n{\n    xxx = camerax();\n    yyy = cameray();\n    \n    if (global.darkzone == 0)\n    {\n        var off = side * 155;\n        draw_sprite_ext(spr_pxwhite, 0, xxx + 16, yyy + 5 + off, 289, 76, 0, c_white, 1);\n        draw_sprite_ext(spr_pxwhite, 0, xxx + 19, yyy + 8 + off, 283, 70, 0, c_black, 1);\n    }\n    \n    if (global.darkzone == 1)\n    {\n        if (side == 0)\n        {\n            draw_set_color(c_black);\n            draw_rectangle(xxx + 38, yyy + 16, xxx + 602, yyy + 154, false);\n            scr_darkbox((xxx + 32) - 8, (yyy + 10) - 8, xxx + 608 + 8, yyy + 160 + 8);\n        }\n        else\n        {\n            draw_set_color(c_black);\n            draw_rectangle(xxx + 38, yyy + 326, xxx + 602, yyy + 464, false);\n            scr_darkbox((xxx + 32) - 8, (yyy + 320) - 8, xxx + 608 + 8, yyy + 470 + 8);\n        }\n    }\n}\n",
    "scr_facechoice": "function scr_facechoice()\n{\n    myface = instance_create(writer.x + (8 * f), writer.y + (5 * f), obj_face);\n}\n",
    "scr_darkbox": "function scr_darkbox(arg0, arg1, arg2, arg3)\n{\n    cur_jewel += 1;\n    textbox_width = arg2 - arg0 - 63;\n    \n    if (textbox_width < 0)\n        textbox_width = 0;\n    \n    textbox_height = arg3 - arg1 - 63;\n    \n    if (textbox_height < 0)\n        textbox_height = 0;\n    \n    if (textbox_width > 0)\n    {\n        draw_sprite_stretched(spr_textbox_top, 0, arg0 + 32, arg1, textbox_width, 32);\n        draw_sprite_ext(spr_textbox_top, 0, arg0 + 32, arg3 + 1, textbox_width, -2, 0, c_white, 1);\n    }\n    \n    if (textbox_height > 0)\n    {\n        draw_sprite_ext(spr_textbox_left, 0, arg2 + 1, arg1 + 32, -2, textbox_height, 0, c_white, 1);\n        draw_sprite_ext(spr_textbox_left, 0, arg0, arg1 + 32, 2, textbox_height, 0, c_white, 1);\n    }\n    \n    if (global.flag[8] == 0)\n    {\n        draw_sprite_ext(spr_textbox_topleft, cur_jewel / 10, arg0, arg1, 2, 2, 0, c_white, 1);\n        draw_sprite_ext(spr_textbox_topleft, cur_jewel / 10, arg2 + 1, arg1, -2, 2, 0, c_white, 1);\n        draw_sprite_ext(spr_textbox_topleft, cur_jewel / 10, arg0, arg3 + 1, 2, -2, 0, c_white, 1);\n        draw_sprite_ext(spr_textbox_topleft, cur_jewel / 10, arg2 + 1, arg3 + 1, -2, -2, 0, c_white, 1);\n    }\n    else\n    {\n        draw_sprite_ext(spr_textbox_topleft, 0, arg0, arg1, 2, 2, 0, c_white, 1);\n        draw_sprite_ext(spr_textbox_topleft, 0, arg2 + 1, arg1, -2, 2, 0, c_white, 1);\n        draw_sprite_ext(spr_textbox_topleft, 0, arg0, arg3 + 1, 2, -2, 0, c_white, 1);\n        draw_sprite_ext(spr_textbox_topleft, 0, arg2 + 1, arg3 + 1, -2, -2, 0, c_white, 1);\n    }\n}\n",
