    "snd_pause": "function snd_pause(arg0)\n{\n    if (global.is_console)\n        snd_volume(arg0, 0, 0);\n    \n    audio_pause_sound(arg0);\n}\n",
    "scr_keyitemget": "function scr_keyitemget(arg0)\n{\n    i = 0;\n    loop = 1;\n    noroom = 0;\n    global.item[12] = 999;\n    \n    while (loop == 1)\n    {\n        if (global.keyitem[i] == 0)\n        {\n            global.keyitem[i] = arg0;\n            break;\n        }\n        \n        if (i == 12)\n        {\n            noroom = 1;\n            break;\n        }\n        \n        i += 1;\n    }\n    \n    script_execute(scr_keyiteminfo_all);\n}\n",
    "scr_cutscene_make": "function scr_cutscene_make()\n{\n    _cutscene_master = instance_create(0, 0, obj_cutscene_master);\n    _cutscene_master.master_object = id;\n    return _cutscene_master;\n}\n",
    "scr_maincharacters_actors": "function scr_maincharacters_actors()\n{\n    actor_count = 0;\n    kr = 0;\n    kr_actor = instance_create(obj_mainchara.x, obj_mainchara.y, obj_actor);\n    scr_actor_setup(kr, kr_actor, \"kris\");\n    kr_actor.sprite_index = obj_mainchara.sprite_index;\n    kr_actor.depth = obj_mainchara.depth;\n    \n    with (obj_mainchara)\n        visible = 0;\n    \n    for (__jj = 0; __jj < array_length_1d(global.cinstance); __jj++)\n    {\n        if (i_ex(global.cinstance[__jj]))\n        {\n            if (global.cinstance[__jj].name == \"susie\")\n            {\n                actor_count++;\n                su = __jj + 1;\n                su_actor = instance_create(global.cinstance[__jj].x, global.cinstance[__jj].y, obj_actor);\n                scr_actor_setup(su, su_actor, \"susie\");\n                su_actor.sprite_index = global.cinstance[__jj].sprite_index;\n                su_actor.depth = global.cinstance[__jj].depth;\n                \n                with (global.cinstance[__jj])\n                    visible = 0;\n            }\n            \n            if (global.cinstance[__jj].name == \"ralsei\")\n            {\n                actor_count++;\n                ra = __jj + 1;\n                ra_actor = instance_create(global.cinstance[__jj].x, global.cinstance[__jj].y, obj_actor);\n                scr_actor_setup(ra, ra_actor, \"ralsei\");\n                ra_actor.sprite_index = global.cinstance[__jj].sprite_index;\n                ra_actor.depth = global.cinstance[__jj].depth;\n                \n                with (global.cinstance[__jj])\n                    visible = 0;\n            }\n            \n            if (global.cinstance[__jj].name == \"noelle\")\n            {\n                actor_count++;\n                no = __jj + 1;\n                no_actor = instance_create(global.cinstance[__jj].x, global.cinstance[__jj].y, obj_actor);\n                scr_actor_setup(no, no_actor, \"noelle\");\n                no_actor.sprite_index = global.cinstance[__jj].sprite_index;\n                no_actor.depth = global.cinstance[__jj].depth;\n                \n                with (global.cinstance[__jj])\n                    visible = 0;\n            }\n        }\n    }\n}\n",
