    "scr_pan_to_obj": "function scr_pan_to_obj(arg0, arg1)\n{\n    _panx = arg0.x - floor((__view_get(e__VW.WView, 0) / 2) - (arg0.sprite_width / 2));\n    _pany = arg0.y - floor((__view_get(e__VW.HView, 0) / 2) - (arg0.sprite_height / 2));\n    \n    if (_panx < 0)\n        _panx = 0;\n    \n    if (_panx >= (room_width - __view_get(e__VW.WView, 0)))\n        _panx = room_width - __view_get(e__VW.WView, 0);\n    \n    if (_pany < 0)\n        _pany = 0;\n    \n    if (_pany >= (room_height - __view_get(e__VW.HView, 0)))\n        _pany = room_height - __view_get(e__VW.HView, 0);\n    \n    scr_pan_lerp(_panx, _pany, arg1);\n}\n\nenum e__VW\n{\n    XView,\n    YView,\n    WView,\n    HView,\n    Angle,\n    HBorder,\n    VBorder,\n    HSpeed,\n    VSpeed,\n    Object,\n    Visible,\n    XPort,\n    YPort,\n    WPort,\n    HPort,\n    Camera,\n    SurfaceID\n}\n",
    "scr_spamton_heal": "function scr_spamton_heal(arg0)\n{\n    with (obj_dmgwriter)\n    {\n        if (delaytimer >= 1)\n            killactive = 1;\n    }\n    \n    for (i = 0; i < 3; i++)\n    {\n        if (global.char[i] == 0)\n            continue;\n        \n        var _hltarget = global.char[i];\n        var _curhp = global.hp[_hltarget];\n        \n        if (arg0 == 0)\n            _healpower = global.maxhp[_hltarget] / 2;\n        else if (arg0 == 1)\n            _healpower = global.maxhp[_hltarget] / 5;\n        else if (arg0 == 2)\n            _healpower = 1;\n        else\n            _healpower = 0;\n        \n        var _healpower = ceil(_healpower);\n        scr_heal(i, _healpower);\n        \n        with (global.charinstance[i])\n        {\n            ha = instance_create(x, y, obj_healanim);\n            ha.target = id;\n            dmgwr = scr_dmgwriter_selfchar();\n            \n            with (dmgwr)\n            {\n                delay = 8;\n                type = 3;\n                damage = _healpower;\n            }\n            \n            if (global.hp[global.char[myself]] >= global.maxhp[global.char[myself]])\n            {\n                with (dmgwr)\n                    specialmessage = 3;\n            }\n            \n            tu += 1;\n        }\n    }\n    \n    for (i = 0; i < 3; i++)\n    {\n        with (global.charinstance[i])\n            tu--;\n    }\n}\n",
    "scr_battle": "function scr_battle(arg0, arg1, arg2, arg3, arg4)\n{\n    global.specialbattle = arg1;\n    global.encounterno = arg0;\n    \n    if (global.flag[9] != 2)\n    {\n        global.flag[9] = 1;\n        global.batmusic[0] = snd_init(\"battle.ogg\");\n    }\n    \n    instance_create(0, 0, obj_battleback);\n    instance_create(0, 0, obj_encounterbasic);\n    __enemymarker[0] = arg2;\n    __enemymarker[1] = arg3;\n    __enemymarker[2] = arg4;\n    \n    for (__ien = 0; __ien < 3; __ien++)\n    {\n        if (global.monstertype[__ien] != 0)\n        {\n            if (!i_ex(__enemymarker[__ien]))\n            {\n                __enemymarker[__ien] = scr_dark_marker(global.monstermakex[__ien] + 300, global.monstermakey[__ien], object_get_sprite(global.monsterinstancetype[__ien]));\n                __enemymarker[__ien].depth = -__ien;\n            }\n            \n            __enemymarker[__ien].__ien = __ien;\n            \n            with (__enemymarker[__ien])\n            {\n                scr_move_to_point_over_time(global.monstermakex[__ien], global.monstermakey[__ien], 20);\n                __doom = instance_create(x, y, obj_doom);\n                __doom.target = id;\n                __doom.alarm[0] = 25;\n            }\n        }\n    }\n}\n",
    "scr_weaponget": "function scr_weaponget(arg0)\n{\n    noroom = 0;\n    var legacy = 0;\n    var __i = 0;\n    \n    if (legacy == 0)\n    {\n        var __itemcount = 0;\n        __weapon[0] = arg0;\n        \n        for (__i = 0; __i < 48; __i++)\n        {\n            if (global.weapon[__i] != 0)\n            {\n                __weapon[__itemcount + 1] = global.weapon[__i];\n                __itemcount++;\n            }\n        }\n        \n        if (__itemcount >= 48)\n        {\n            noroom = 1;\n        }\n        else\n        {\n            for (__i = 0; __i < 48; __i++)\n            {\n                if (__i <= __itemcount)\n                    global.weapon[__i] = __weapon[__i];\n                else\n                    global.weapon[__i] = 0;\n            }\n        }\n    }\n    else if (legacy)\n    {\n        loop = 1;\n        global.weapon[48] = 999;\n        \n        while (loop == 1)\n        {\n            if (global.weapon[__i] == 0)\n            {\n                global.weapon[__i] = arg0;\n                break;\n            }\n            \n            if (__i == 48)\n            {\n                noroom = 1;\n                break;\n            }\n            \n            __i += 1;\n        }\n    }\n    \n    script_execute(scr_weaponinfo_all);\n}\n",
    "scr_draw_sprite_tiled_area": "function scr_draw_sprite_tiled_area()\n{\n    var sprite = argument[0];\n    var subimg = argument[1];\n    var xx = argument[2];\n    var yy = argument[3];\n    var x1 = argument[4];\n    var y1 = argument[5];\n    var x2 = argument[6];\n    var y2 = argument[7];\n    var xscale = argument[8];\n    var yscale = argument[9];\n    var col = (argument_count > 10) ? argument[10] : 16777215;\n    var alpha = (argument_count > 11) ? argument[11] : 1;\n    var sw = sprite_get_width(sprite) * xscale;\n    var sh = sprite_get_height(sprite) * yscale;\n    var i = x1 - ((x1 % sw) - (xx % sw)) - (sw * ((x1 % sw) < (xx % sw)));\n    var j = y1 - ((y1 % sh) - (yy % sh)) - (sh * ((y1 % sh) < (yy % sh)));\n    var jj = j;\n    \n    while (i <= x2)\n    {\n        while (j <= y2)\n        {\n            var left;\n            \n            if (i <= x1)\n                left = x1 - i;\n            else\n                left = 0;\n            \n            var X = i + left;\n            var top;\n            \n            if (j <= y1)\n                top = y1 - j;\n            else\n                top = 0;\n            \n            var Y = j + top;\n            var width;\n            \n            if (x2 <= (i + sw))\n                width = ((sw - ((i + sw) - x2)) + 1) - left;\n            else\n                width = sw - left;\n            \n            var height;\n            \n            if (y2 <= (j + sh))\n                height = ((sh - ((j + sh) - y2)) + 1) - top;\n            else\n                height = sh - top;\n            \n            draw_sprite_part_ext(sprite, subimg, left, top, width, height, X, Y, xscale, yscale, col, alpha);\n            j += sh;\n        }\n        \n        j = jj;\n        i += sw;\n    }\n    \n    return 0;\n}\n",
