    "ease_in_elastic": "function ease_in_elastic(arg0, arg1, arg2, arg3)\n{\n    var _s = 1.70158;\n    var _p = 0;\n    var _a = arg2;\n    \n    if (arg0 == 0 || _a == 0)\n        return arg1;\n    \n    arg0 /= arg3;\n    \n    if (arg0 == 1)\n        return arg1 + arg2;\n    \n    if (_p == 0)\n        _p = arg3 * 0.3;\n    \n    if (_a < abs(arg2))\n    {\n        _a = arg2;\n        _s = _p * 0.25;\n    }\n    else\n    {\n        _s = (_p / (2 * pi)) * arcsin(arg2 / _a);\n    }\n    \n    return -(_a * power(2, 10 * --arg0) * sin((((arg0 * arg3) - _s) * (2 * pi)) / _p)) + arg1;\n}\n",
    "ease_out_bounce": "function ease_out_bounce(arg0, arg1, arg2, arg3)\n{\n    arg0 /= arg3;\n    \n    if (arg0 < 0.36363636363636365)\n    {\n        return (arg2 * (7.5625 * arg0 * arg0)) + arg1;\n    }\n    else if (arg0 < 0.7272727272727273)\n    {\n        arg0 -= 0.5454545454545454;\n        return (arg2 * ((7.5625 * arg0 * arg0) + 0.75)) + arg1;\n    }\n    else if (arg0 < 0.9090909090909091)\n    {\n        arg0 -= 0.8181818181818182;\n        return (arg2 * ((7.5625 * arg0 * arg0) + 0.9375)) + arg1;\n    }\n    else\n    {\n        arg0 -= 0.9545454545454546;\n        return (arg2 * ((7.5625 * arg0 * arg0) + 0.984375)) + arg1;\n    }\n}\n",
    "ease_out_back": "function ease_out_back(arg0, arg1, arg2, arg3)\n{\n    var _s = 1.70158;\n    arg0 = (arg0 / arg3) - 1;\n    return (arg2 * ((arg0 * arg0 * (((_s + 1) * arg0) + _s)) + 1)) + arg1;\n}\n",
    "ease_inout_bounce": "function ease_inout_bounce(arg0, arg1, arg2, arg3)\n{\n    if (arg0 < (arg3 * 0.5))\n        return (ease_in_bounce(arg0 * 2, 0, arg2, arg3) * 0.5) + arg1;\n    \n    return (ease_out_bounce((arg0 * 2) - arg3, 0, arg2, arg3) * 0.5) + (arg2 * 0.5) + arg1;\n}\n",
    "ease_inout_elastic": "function ease_inout_elastic(arg0, arg1, arg2, arg3)\n{\n    var _s = 1.70158;\n    var _p = 0;\n    var _a = arg2;\n    \n    if (arg0 == 0 || _a == 0)\n        return arg1;\n    \n    arg0 /= (arg3 * 0.5);\n    \n    if (arg0 == 2)\n        return arg1 + arg2;\n    \n    if (!_p)\n        _p = arg3 * 0.44999999999999996;\n    \n    if (_a < abs(arg2))\n    {\n        _a = arg2;\n        _s = _p * 0.25;\n    }\n    else\n    {\n        _s = (_p / (2 * pi)) * arcsin(arg2 / _a);\n    }\n    \n    if (arg0 < 1)\n        return (-0.5 * (_a * power(2, 10 * --arg0) * sin((((arg0 * arg3) - _s) * (2 * pi)) / _p))) + arg1;\n    \n    return (_a * power(2, -10 * --arg0) * sin((((arg0 * arg3) - _s) * (2 * pi)) / _p) * 0.5) + arg2 + arg1;\n}\n",
    "ease_inout_back": "function ease_inout_back(arg0, arg1, arg2, arg3)\n{\n    var _s = 1.70158;\n    arg0 /= arg3;\n    arg0 *= 2;\n    \n    if (arg0 < 1)\n    {\n        _s *= 1.525;\n        return (arg2 * 0.5 * (arg0 * arg0 * (((_s + 1) * arg0) - _s))) + arg1;\n    }\n    \n    arg0 -= 2;\n    _s *= 1.525;\n    return (arg2 * 0.5 * ((arg0 * arg0 * (((_s + 1) * arg0) + _s)) + 2)) + arg1;\n}\n",
    "scr_damage_cache": "function scr_damage_cache()\n{\n    global.damage_cache = [];\n    \n    for (var i = 0; i < 3; i++)\n        global.damage_cache[array_length(global.damage_cache)] = global.hp[global.char[i]];\n}\n\nfunction scr_damage_check()\n{\n    if (!variable_global_exists(\"damage_cache\"))\n        global.damage_cache = [];\n    \n    var took_damage = false;\n    \n    for (var i = 0; i < array_length(global.damage_cache); i++)\n    {\n        var hp_cache = global.damage_cache[i];\n        \n        if (global.hp[global.char[i]] < hp_cache)\n        {\n            took_damage = true;\n            break;\n        }\n    }\n    \n    if (took_damage)\n    {\n        with (obj_event_manager)\n            trigger_event(UnknownEnum.Value_1);\n    }\n}\n\nenum UnknownEnum\n{\n    Value_1 = 1\n}\n",
    "scr_heal": "function scr_heal(arg0, arg1)\n{\n    abovemaxhp = 0;\n    belowzero = 0;\n    hltarget = global.char[arg0];\n    _curhp = global.hp[hltarget];\n    \n    if (global.hp[hltarget] <= 0)\n        belowzero = 1;\n    \n    if (global.hp[hltarget] > global.maxhp[hltarget])\n        abovemaxhp = 1;\n    \n    if (abovemaxhp == 0)\n    {\n        global.hp[hltarget] += arg1;\n        \n        if (global.hp[hltarget] > global.maxhp[hltarget])\n            global.hp[hltarget] = global.maxhp[hltarget];\n    }\n    \n    if (belowzero == 1 && global.hp[hltarget] >= 0)\n    {\n        if (global.hp[hltarget] < ceil(global.maxhp[hltarget] / 6))\n            global.hp[hltarget] = ceil(global.maxhp[hltarget] / 6);\n        \n        scr_revive(arg0);\n    }\n    \n    snd_stop(snd_power);\n    snd_play(snd_power);\n    return global.hp[hltarget] - _curhp;\n}\n",
