    "scr_itemcheck": "function scr_itemcheck(arg0)\n{\n    haveit = 0;\n    itemcount = 0;\n    \n    for (var __i = 0; __i < 12; __i += 1)\n    {\n        if (global.item[__i] == arg0)\n            haveit = 1;\n        \n        if (global.item[__i] == arg0)\n            itemcount += 1;\n    }\n    \n    return haveit;\n}\n",
    "scr_recruits_to_array": "function scr_recruits_to_array()\n{\n    var startnum = 0;\n    var endnum = 50;\n    var whichrecruit = \"full\";\n    \n    if (argument_count >= 1)\n        whichrecruit = argument[0];\n    \n    if (argument_count >= 2)\n    {\n        if (argument[1] == 1)\n            endnum = 25;\n        \n        if (argument[1] == 2)\n            startnum = 30;\n    }\n    \n    recruit[0] = 0;\n    totalrecruits = 0;\n    halfrecruits = 0;\n    eitherrecruits = 0;\n    \n    for (var i = startnum; i < endnum; i++)\n    {\n        if (global.flag[i + 600] > 0)\n        {\n            if (whichrecruit == \"either\")\n                recruit[eitherrecruits] = i;\n            \n            eitherrecruits++;\n            \n            if (global.flag[i + 600] == 1)\n            {\n                if (whichrecruit == \"full\")\n                    recruit[totalrecruits] = i;\n                \n                totalrecruits++;\n            }\n            else\n            {\n                if (whichrecruit == \"half\")\n                    recruit[halfrecruits] = i;\n                \n                halfrecruits++;\n            }\n        }\n    }\n    \n    return totalrecruits;\n}\n",
    "scr_itemremove": "function scr_itemremove(arg0)\n{\n    removed = 0;\n    scr_itemcheck(arg0);\n    \n    if (haveit == 1)\n    {\n        loc = 0;\n        skip = 0;\n        \n        if (global.item[0] == arg0 && skip == 0)\n        {\n            loc = 0;\n            skip = 1;\n        }\n        \n        if (global.item[1] == arg0 && skip == 0)\n        {\n            loc = 1;\n            skip = 1;\n        }\n        \n        if (global.item[2] == arg0 && skip == 0)\n        {\n            loc = 2;\n            skip = 1;\n        }\n        \n        if (global.item[3] == arg0 && skip == 0)\n        {\n            loc = 3;\n            skip = 1;\n        }\n        \n        if (global.item[4] == arg0 && skip == 0)\n        {\n            loc = 4;\n            skip = 1;\n        }\n        \n        if (global.item[5] == arg0 && skip == 0)\n        {\n            loc = 5;\n            skip = 1;\n        }\n        \n        if (global.item[6] == arg0 && skip == 0)\n        {\n            loc = 6;\n            skip = 1;\n        }\n        \n        if (global.item[7] == arg0 && skip == 0)\n        {\n            loc = 7;\n            skip = 1;\n        }\n        \n        if (global.item[8] == arg0 && skip == 0)\n        {\n            loc = 8;\n            skip = 1;\n        }\n        \n        if (global.item[9] == arg0 && skip == 0)\n        {\n            loc = 9;\n            skip = 1;\n        }\n        \n        if (global.item[10] == arg0 && skip == 0)\n        {\n            loc = 10;\n            skip = 1;\n        }\n        \n        if (global.item[11] == arg0 && skip == 0)\n        {\n            loc = 11;\n            skip = 1;\n        }\n        \n        scr_itemshift(loc, 0);\n        removed = 1;\n    }\n}\n",
    "scr_weaponremove": "function scr_weaponremove(arg0)\n{\n    __i = 0;\n    __loop = 1;\n    __inventorysize = array_length_1d(global.weapon);\n    \n    while (__loop == 1)\n    {\n        if (global.weapon[__i] == arg0)\n        {\n            global.weapon[__i] = 0;\n            break;\n        }\n        \n        if (i == __inventorysize)\n        {\n            __loop = 0;\n            break;\n        }\n        \n        __i += 1;\n    }\n    \n    script_execute(scr_weaponinfo_all);\n}\n",
    "scr_armorremove": "function scr_armorremove(arg0)\n{\n    __i = 0;\n    var loop = 1;\n    __inventorysize = array_length_1d(global.armor);\n    \n    while (loop == 1)\n    {\n        if (global.armor[__i] == arg0)\n        {\n            global.armor[__i] = 0;\n            break;\n        }\n        \n        if (__i == __inventorysize)\n        {\n            loop = 0;\n            break;\n        }\n        \n        __i += 1;\n    }\n    \n    script_execute(scr_armorinfo_all);\n}\n",
    "scr_armorget": "function scr_armorget(arg0)\n{\n    noroom = 0;\n    var legacy = 0;\n    var __i = 0;\n    \n    if (legacy == 0)\n    {\n        var __itemcount = 0;\n        __armor[0] = arg0;\n        \n        for (__i = 0; __i < 48; __i++)\n        {\n            if (global.armor[__i] != 0)\n            {\n                __armor[__itemcount + 1] = global.armor[__i];\n                __itemcount++;\n            }\n        }\n        \n        if (__itemcount >= 48)\n        {\n            noroom = 1;\n        }\n        else\n        {\n            for (__i = 0; __i < 48; __i++)\n            {\n                if (__i <= __itemcount)\n                    global.armor[__i] = __armor[__i];\n                else\n                    global.armor[__i] = 0;\n            }\n        }\n    }\n    else if (legacy)\n    {\n        loop = 1;\n        global.armor[48] = 999;\n        \n        while (loop == 1)\n        {\n            if (global.armor[__i] == 0)\n            {\n                global.armor[__i] = arg0;\n                break;\n            }\n            \n            if (__i == 48)\n            {\n                noroom = 1;\n                break;\n            }\n            \n            __i += 1;\n        }\n    }\n    \n    script_execute(scr_armorinfo_all);\n}\n",
