    "scr_controls_default": "function scr_controls_default()\n{\n    global.button0 = gp_face1;\n    global.button1 = gp_face2;\n    global.button2 = gp_face4;\n    \n    if (os_type == os_ps4 || os_type == os_ps5)\n    {\n        var os_map = os_get_info();\n        var ps4_confirm_button = undefined;\n        \n        if (os_map != -1)\n        {\n            var mapsize = ds_map_size(os_map);\n            var key = ds_map_find_first(os_map);\n            \n            for (var i = 0; i < (mapsize - 1); i++)\n            {\n                if (key == \"enter_button_assign\")\n                    ps4_confirm_button = ds_map_find_value(os_map, key);\n                else\n                    key = ds_map_find_next(os_map, key);\n            }\n            \n            ds_map_destroy(os_map);\n        }\n        \n        if (ps4_confirm_button == 0)\n        {\n            global.button0 = gp_face2;\n            global.button1 = gp_face1;\n        }\n        else\n        {\n            global.button0 = gp_face1;\n            global.button1 = gp_face2;\n        }\n        \n        global.button2 = gp_face4;\n    }\n    else if (scr_is_switch_os())\n    {\n        global.button0 = gp_face2;\n        global.button1 = gp_face1;\n        global.button2 = gp_face4;\n    }\n    \n    global.default_button0 = global.button0;\n    global.default_button1 = global.button1;\n    global.default_button2 = global.button2;\n    global.input_k[0] = vk_down;\n    global.input_k[1] = vk_right;\n    global.input_k[2] = vk_up;\n    global.input_k[3] = vk_left;\n    global.input_k[4] = ord(\"Z\");\n    global.input_k[5] = ord(\"X\");\n    global.input_k[6] = ord(\"C\");\n    global.input_k[7] = vk_enter;\n    global.input_k[8] = vk_shift;\n    global.input_k[9] = vk_control;\n    global.input_g[0] = gp_padd;\n    global.input_g[1] = gp_padr;\n    global.input_g[2] = gp_padu;\n    global.input_g[3] = gp_padl;\n    global.input_g[4] = global.button0;\n    global.input_g[5] = global.button1;\n    global.input_g[6] = global.button2;\n    global.input_g[7] = 999;\n    global.input_g[8] = 999;\n    global.input_g[9] = 999;\n    obj_gamecontroller.gamepad_shoulderlb_reassign = 0;\n}\n",
    "ossafe_ini_open": "function ossafe_ini_open(arg0)\n{\n    if (!global.is_console)\n    {\n        ini_open(arg0);\n    }\n    else\n    {\n        var name = string_lower(arg0);\n        global.current_ini = name;\n        var file = ds_map_find_value(global.savedata, name);\n        var data;\n        \n        if (is_undefined(file))\n            data = \"\";\n        else\n            data = file;\n        \n        ini_open_from_string(data);\n    }\n}\n",
    "ossafe_ini_close": "function ossafe_ini_close()\n{\n    if (!global.is_console)\n    {\n        return ini_close();\n    }\n    else if (!is_undefined(global.current_ini))\n    {\n        ds_map_set(global.savedata, global.current_ini, ini_close());\n        global.current_ini = undefined;\n    }\n}\n",
    "ossafe_savedata_save": "function ossafe_savedata_save()\n{\n    if (!global.is_console)\n    {\n    }\n    else\n    {\n        if (global.savedata_async_id >= 0 || global.savedata_async_load)\n            return 0;\n        \n        var slot_size = 31457280;\n        buffer_async_group_begin(\"Deltarune\");\n        buffer_async_group_option(\"showdialog\", 0);\n        buffer_async_group_option(\"savepadindex\", 0);\n        buffer_async_group_option(\"slottitle\", \"DELTARUNE\");\n        buffer_async_group_option(\"subtitle\", \"DELTARUNE Save Data\");\n        buffer_async_group_option(\"saveslotsize\", slot_size);\n        var json = json_encode(global.savedata);\n        global.savedata_buffer = buffer_create(string_byte_length(json) + 1, buffer_grow, 1);\n        buffer_write(global.savedata_buffer, buffer_string, json);\n        buffer_save_async(global.savedata_buffer, \"deltarune.sav\", 0, buffer_get_size(global.savedata_buffer));\n        global.savedata_async_load = false;\n        global.savedata_debuginfo = \"save in progress\";\n        global.savedata_async_id = buffer_async_group_end();\n    }\n}\n",
