    "scr_84_get_sprite": "function scr_84_get_sprite(arg0)\n{\n    return ds_map_find_value(global.chemg_sprite_map, arg0);\n}\n",
    "scr_get_input_name": "function scr_get_input_name(arg0)\n{\n    var _control = \"[?]\";\n    \n    if (global.is_console || obj_gamecontroller.gamepad_active)\n    {\n        _control = global.input_g[arg0];\n        \n        if (_control == gp_padr)\n            return \"\\\\*D  \";\n        \n        if (_control == gp_padl)\n            return \"\\\\*A  \";\n        \n        if (_control == global.button0)\n            return \"\\\\*Z  \";\n        \n        if (_control == global.button1)\n            return \"\\\\*X  \";\n        \n        if (_control == global.button2)\n            return \"\\\\*C  \";\n    }\n    \n    var left_bracket = (global.lang == \"en\") ? \"[\" : \"[\";\n    var right_bracket = (global.lang == \"en\") ? \"]\" : \"]\";\n    _control = left_bracket + global.asc_def[global.input_k[arg0]] + right_bracket;\n    \n    if (!is_string(_control))\n        _control = \"[?]\";\n    else\n        return _control;\n}\n",
    "scr_move_to_point_over_time": "function scr_move_to_point_over_time(arg0, arg1, arg2)\n{\n    _mmm = instance_create(x, y, obj_move_to_point);\n    _mmm.target = id;\n    _mmm.movex = arg0;\n    _mmm.movey = arg1;\n    _mmm.movemax = arg2;\n}\n",
    "scr_marker": "function scr_marker(arg0, arg1, arg2)\n{\n    thismarker = instance_create(arg0, arg1, obj_marker);\n    \n    with (thismarker)\n    {\n        sprite_index = arg2;\n        image_speed = 0;\n    }\n    \n    return thismarker;\n}\n",
    "scr_itemcheck": "function scr_itemcheck(arg0)\n{\n    haveit = 0;\n    itemcount = 0;\n    \n    for (i = 0; i < 12; i += 1)\n    {\n        if (global.item[i] == arg0)\n            haveit = 1;\n        \n        if (global.item[i] == arg0)\n            itemcount += 1;\n    }\n    \n    return haveit;\n}\n",
    "scr_weaponcheck_inventory": "function scr_weaponcheck_inventory(arg0)\n{\n    haveit = 0;\n    itemcount = 0;\n    \n    for (i = 0; i < 12; i += 1)\n    {\n        if (global.weapon[i] == arg0)\n            haveit = 1;\n        \n        if (global.weapon[i] == arg0)\n            itemcount += 1;\n    }\n    \n    return haveit;\n}\n",
    "scr_rurusface": "function scr_rurusface(arg0, arg1)\n{\n    global.msg[arg0] = scr_84_get_subst_string(scr_84_get_lang_string(\"scr_rurusface_slash_scr_rurusface_gml_1_0\"), string(arg1));\n}\n",
    "scr_litemget": "function scr_litemget(arg0)\n{\n    i = 0;\n    loop = 1;\n    noroom = 0;\n    global.litem[8] = 999;\n    \n    while (loop == 1)\n    {\n        if (global.litem[i] == 0)\n        {\n            global.litem[i] = arg0;\n            break;\n        }\n        \n        if (i == 8)\n        {\n            noroom = 1;\n            break;\n        }\n        \n        i += 1;\n    }\n    \n    scr_litemname();\n}\n",
    "scr_defeatrun": "function scr_defeatrun()\n{\n    defeatanim = instance_create(x, y, obj_defeatanim);\n    defeatanim.sprite_index = sprite_index;\n    defeatanim.sprite_index = hurtsprite;\n    defeatanim.image_index = 0;\n    defeatanim.image_xscale = image_xscale;\n    defeatanim.image_yscale = image_yscale;\n    instance_destroy();\n}\n",
    "scr_afterimage": "function scr_afterimage()\n{\n    afterimage = instance_create(x, y, obj_afterimage);\n    afterimage.sprite_index = sprite_index;\n    afterimage.image_index = image_index;\n    afterimage.image_blend = image_blend;\n    afterimage.image_speed = 0;\n    afterimage.depth = depth;\n    afterimage.image_xscale = image_xscale;\n    afterimage.image_yscale = image_yscale;\n    afterimage.image_angle = image_angle;\n    return afterimage;\n}\n",
    "scr_kingface": "function scr_kingface(arg0, arg1)\n{\n    if (global.plot >= 235)\n        global.msg[arg0] = scr_84_get_subst_string(scr_84_get_lang_string(\"scr_kingface_slash_scr_kingface_gml_3_0\"), string(arg1));\n    else\n        global.msg[arg0] = scr_84_get_subst_string(scr_84_get_lang_string(\"scr_kingface_slash_scr_kingface_gml_7_0\"), string(arg1));\n}\n",
