    "scr_fire_bullet": "function scr_fire_bullet(arg0, arg1, arg2, arg3, arg4, arg5 = -4, arg6 = 0, arg7 = false, arg8 = 87135)\n{\n    var bullet;\n    \n    if (arg8 != 87135)\n        bullet = instance_create_depth(arg0, arg1, arg8, arg2);\n    else\n        bullet = instance_create(arg0, arg1, arg2);\n    \n    with (bullet)\n    {\n        direction = arg3;\n        speed = arg4;\n        \n        if (arg5 != -4)\n            sprite_index = arg5;\n        \n        updateimageangle = arg6;\n        \n        if (arg6)\n            image_angle = arg3;\n        \n        if (arg7)\n        {\n            with (other)\n                scr_bullet_inherit(other.id);\n        }\n    }\n    \n    return bullet;\n}\n\nfunction scr_fire_bullet_colorize(arg0, arg1, arg2, arg3, arg4, arg5, arg6, arg7 = 0)\n{\n    var bullet = instance_create(arg0, arg1, arg2);\n    \n    with (bullet)\n    {\n        direction = arg3;\n        speed = arg4;\n        sprite_index = arg5;\n        image_blend = arg6;\n        updateimageangle = arg7;\n        \n        if (arg7)\n            image_angle = arg3;\n    }\n    \n    return bullet;\n}\n",
    "scr_approach": "function scr_approach(arg0, arg1, arg2)\n{\n    if (arg0 < arg1)\n    {\n        arg0 += arg2;\n        \n        if (arg0 > arg1)\n            return arg1;\n    }\n    else\n    {\n        arg0 -= arg2;\n        \n        if (arg0 < arg1)\n            return arg1;\n    }\n    \n    return arg0;\n}\n",
    "scr_script_repeat": "function scr_script_repeat()\n{\n    var __scriptdelay = instance_create(0, 0, obj_script_delayed);\n    __scriptdelay.script = argument[0];\n    __scriptdelay.alarm[0] = -2;\n    __scriptdelay.max_time = argument[1];\n    __scriptdelay.rate = argument[2];\n    __scriptdelay.constant = 1;\n    __scriptdelay.target = id;\n    \n    for (var __i = 0; __i < (argument_count - 3); __i++)\n        __scriptdelay.script_arg[__i] = argument[__i + 3];\n    \n    __scriptdelay.arg_count = argument_count - 3;\n    return __scriptdelay;\n}\n",
    "scr_doom": "function scr_doom(arg0, arg1)\n{\n    var _doom = instance_create_depth(0, 0, 0, obj_doom);\n    \n    with (_doom)\n    {\n        alarm[0] = arg1;\n        target = arg0;\n    }\n    \n    return _doom;\n}\n",
    "snd_play_delay": "function snd_play_delay(arg0, arg1, arg2 = 0.7, arg3 = 1)\n{\n    scr_script_delayed(snd_play, arg1, arg0, arg2, arg3);\n}\n\nfunction snd_play_delayed(arg0, arg1, arg2 = 0.7, arg3 = 1)\n{\n    scr_script_delayed(snd_play, arg1, arg0, arg2, arg3);\n}\n\nfunction soundplay_delay(arg0, arg1, arg2 = 0.7, arg3 = 1)\n{\n    scr_script_delayed(snd_play, arg1, arg0, arg2, arg3);\n}\n\nfunction sound_play_delay(arg0, arg1, arg2 = 0.7, arg3 = 1)\n{\n    scr_script_delayed(snd_play, arg1, arg0, arg2, arg3);\n}\n",
