    "scr_get_box": "function scr_get_box(arg0)\n{\n    switch (arg0)\n    {\n        case 0:\n            return obj_growtangle.x + (obj_growtangle.sprite_width * 0.5);\n            break;\n        \n        case 1:\n            return obj_growtangle.y - (obj_growtangle.sprite_height * 0.5);\n            break;\n        \n        case 2:\n            return obj_growtangle.x - (obj_growtangle.sprite_width * 0.5);\n            break;\n        \n        case 3:\n            return obj_growtangle.y + (obj_growtangle.sprite_height * 0.5);\n            break;\n        \n        case 4:\n            return obj_growtangle.x;\n            break;\n        \n        case 5:\n            return obj_growtangle.y;\n            break;\n            return false;\n    }\n}\n",
    "scr_wrap": "function scr_wrap(arg0, arg1, arg2)\n{\n    if ((arg0 % 1) == 0)\n    {\n        while (arg0 > arg2 || arg0 < arg1)\n        {\n            if (arg0 > arg2)\n            {\n                arg0 = (arg1 + arg0) - arg2 - 1;\n            }\n            else if (arg0 < arg1)\n            {\n                arg0 = ((arg2 + arg0) - arg1) + 1;\n            }\n            else\n            {\n            }\n        }\n        \n        return arg0;\n    }\n    else\n    {\n        var _old = argument[0] + 1;\n        \n        while (arg0 != _old)\n        {\n            _old = arg0;\n            \n            if (arg0 < arg1)\n            {\n                arg0 = arg2 - (arg1 - arg0);\n            }\n            else if (arg0 > arg2)\n            {\n                arg0 = arg1 + (arg0 - arg2);\n            }\n            else\n            {\n            }\n        }\n        \n        return arg0;\n    }\n}\n",
    "scr_moveheart": "function scr_moveheart()\n{\n    global.inv = 0;\n    return instance_create(obj_herokris.x + 10, obj_herokris.y + 40, obj_moveheart);\n}\n",
