    "cameraheight": "function cameraheight()\n{\n    return __view_get(e__VW.HView, 0);\n}\n\nenum e__VW\n{\n    XView,\n    YView,\n    WView,\n    HView,\n    Angle,\n    HBorder,\n    VBorder,\n    HSpeed,\n    VSpeed,\n    Object,\n    Visible,\n    XPort,\n    YPort,\n    WPort,\n    HPort,\n    Camera,\n    SurfaceID\n}\n",
    "snd_pitch": "function snd_pitch(arg0, arg1)\n{\n    audio_sound_pitch(arg0, arg1);\n}\n\nfunction sound_pitch(arg0, arg1)\n{\n    snd_pitch(arg0, arg1);\n}\n",
    "snd_init": "function snd_init(arg0)\n{\n    var dir = \"mus/\";\n    \n    if (global.launcher)\n        dir = working_directory + \"../mus/\";\n    \n    initsongvar = dir + arg0;\n    _mystream = audio_create_stream(initsongvar);\n    _astream = instance_create(0, 0, obj_astream);\n    _astream.mystream = _mystream;\n    _astream.songname = arg0;\n    return _mystream;\n}\n\nfunction sound_init(arg0)\n{\n    snd_init(arg0);\n}\n",
    "mus_loop_ext": "function mus_loop_ext(arg0, arg1, arg2)\n{\n    snd_volume(arg0, arg1 * global.flag[16], 0);\n    snd_pitch(arg0, arg2);\n    return mus_loop(arg0);\n}\n",
    "scr_enemy_object_init": "function scr_enemy_object_init()\n{\n    becomeflash = 0;\n    flash = 0;\n    turnt = 0;\n    turns = 0;\n    talktimer = 0;\n    state = 0;\n    siner = 0;\n    fsiner = 0;\n    talked = 0;\n    attacked = 0;\n    hurt = 0;\n    hurttimer = 0;\n    hurtshake = 0;\n    shakex = 0;\n    mywriter = 343249823;\n    acttimer = 0;\n    con = 0;\n    dodgetimer = 0;\n    fatal = 0;\n    candodge = 0;\n    mytarget = 0;\n    ambushed = 0;\n    firststrike = 0;\n    damage = 1;\n    grazepoints = 0;\n    timepoints = 0;\n    \n    if (object_index == obj_aqua_enemy)\n        timepoints = 1;\n    \n    inv = -1;\n    target = -1;\n    grazed = -1;\n    grazetimer = -1;\n    element = \"none\";\n    acting = 0;\n    actcon = 0;\n    actingsus = 0;\n    actingnoe = 0;\n    actingral = 0;\n    actconsus = 0;\n    actconral = 0;\n    actconnoe = 0;\n    simulorderkri = -1;\n    simulordersus = -1;\n    simulorderral = -1;\n    simulordernoe = -1;\n    simultotal = 0;\n    simulboss = -1;\n    talkmax = 90;\n    mercymod = 0;\n    maxmercy = 100;\n    recruitable = 1;\n    freezable = 1;\n    recruitcount = 1;\n    sactionboxx = 0;\n    sactionboxy = 0;\n    hurtspriteoffx = 0;\n    hurtspriteoffy = 0;\n    image_xscale = 2;\n    image_yscale = 2;\n    image_speed = 0.2;\n    idlesprite = spr_diamond_knight_overworld;\n    hurtsprite = spr_diamond_knight_hurt;\n    sparedsprite = spr_diamond_knight_spared;\n    custombody = 0;\n    setbattlemsg = false;\n    \n    for (i = 0; i < 10; i++)\n        _charactsprite[i] = 382938298329;\n    \n    depth = 90 - ((y - cameray()) / 50);\n}\n",
    "scr_array_shuffle": "function scr_array_shuffle(arg0)\n{\n    var _len = array_length(arg0);\n    var _last = 0;\n    var _i = 0;\n    \n    while (_len)\n    {\n        _i = irandom(--_len);\n        _last = arg0[_len];\n        arg0[_len] = arg0[_i];\n        arg0[_i] = _last;\n    }\n    \n    return arg0;\n}\n",
    "stringsetloc": "function stringsetloc(arg0, arg1)\n{\n    var str = arg0;\n    \n    if (!is_english())\n        str = scr_84_get_lang_string(arg1);\n    \n    return stringset(str);\n}\n",
    "shader_replace_simple_macros": "function shader_replace_simple_reset_hook()\n{\n    shader_reset();\n    shader_replace_simple_sync(-1);\n}\n\nfunction shader_replace_simple_set_hook()\n{\n    shader_set(argument0);\n    shader_replace_simple_sync(argument0);\n}\n\nfunction shader_replace_simple_macros()\n{\n}\n",
    "d3d_set_fog": "function d3d_set_fog(arg0, arg1, arg2, arg3)\n{\n    gpu_set_fog(arg0, arg1, arg2, arg3);\n}\n",
    "scr_enemy_drawidle_generic": "function scr_enemy_drawidle_generic(arg0)\n{\n    if (state == 0)\n    {\n        fsiner += 1;\n        siner += arg0;\n        thissprite = idlesprite;\n        \n        if (global.mercymod[myself] >= global.mercymax[myself])\n            thissprite = sparedsprite;\n        \n        draw_monster_body_part(thissprite, siner, x, y);\n    }\n}\n",
    "draw_monster_body_part": "function draw_monster_body_part(arg0, arg1, arg2, arg3)\n{\n    draw_sprite_ext(arg0, arg1, arg2, arg3, image_xscale, image_yscale, image_angle, image_blend, image_alpha);\n    \n    if (flash == 1)\n        draw_sprite_ext_flash(arg0, arg1, arg2, arg3, image_xscale, image_yscale, image_angle, image_blend, (-cos(fsiner / 5) * 0.4) + 0.6);\n}\n\nfunction draw_monster_body_part_netskietail(arg0, arg1, arg2, arg3, arg4)\n{\n    draw_sprite_ext(arg0, arg1, arg2, arg3, image_xscale, image_yscale, image_angle, image_blend, arg4);\n    \n    if (flash == 1)\n        draw_sprite_ext_flash(arg0, arg1, arg2, arg3, image_xscale, image_yscale, image_angle, image_blend, (-cos(fsiner / 5) * 0.4) + 0.6);\n}\n",
