    "scr_marker_fog": "function scr_marker_fog(arg0, arg1, arg2, arg3 = 16777215, arg4 = 1, arg5 = 1, arg6 = 0, arg7 = 0, arg8 = 16777215, arg9 = depth, arg10 = false, arg11 = -1, arg12 = 1)\n{\n    var thismarker = instance_create(arg0, arg1, obj_marker_fog);\n    \n    with (thismarker)\n    {\n        depth = arg9;\n        sprite_index = arg2;\n        image_speed = arg6;\n        image_xscale = arg4;\n        image_yscale = arg5;\n        image_index = arg7;\n        image_blend = arg8;\n        image_alpha = arg12;\n        \n        if (arg10)\n            scr_depth_alt();\n        \n        color = arg3;\n    }\n    \n    if (arg11 > 0)\n        scr_doom(thismarker, arg11);\n    \n    return thismarker;\n}\n\nfunction scr_afterimage_fog(arg0 = id, arg1 = 16777215, arg2 = 30)\n{\n    var fog = instance_create(x, y, obj_marker_fog);\n    fog.sprite_index = arg0.sprite_index;\n    fog.image_alpha = arg0.image_alpha;\n    fog.image_angle = arg0.image_angle;\n    fog.image_blend = arg0.image_blend;\n    fog.image_index = arg0.image_index;\n    fog.image_speed = arg0.image_speed;\n    fog.image_xscale = arg0.image_xscale;\n    fog.image_yscale = arg0.image_yscale;\n    fog.mask_index = arg0.mask_index;\n    fog.color = arg1;\n    \n    with (fog)\n        scr_lerpvar(\"image_alpha\", image_alpha, 0, arg2);\n    \n    scr_doom(fog, arg2 + 1);\n    return fog;\n}\n",
