    "scr_draw_outline": "function scr_draw_outline(arg0, arg1, arg2)\n{\n    gpu_set_fog(true, arg1, 0, 0);\n    var __xdirA = arg0;\n    var __xdirB = 0;\n    var __ydirA = 0;\n    var __ydirB = arg0;\n    \n    if ((image_angle % 90) != 0)\n    {\n        __xdirA = lengthdir_x(arg0, image_angle);\n        __xdirB = lengthdir_x(arg0, image_angle + 90);\n        __ydirA = lengthdir_y(arg0, image_angle + 90);\n        __ydirB = lengthdir_y(arg0, image_angle);\n    }\n    \n    draw_sprite_ext(sprite_index, image_index, x + __xdirA, y + __ydirA, image_xscale, image_yscale, image_angle, c_white, image_alpha * arg2);\n    draw_sprite_ext(sprite_index, image_index, x - __xdirA, y - __ydirA, image_xscale, image_yscale, image_angle, c_white, image_alpha * arg2);\n    draw_sprite_ext(sprite_index, image_index, x + __xdirB, y + __ydirB, image_xscale, image_yscale, image_angle, c_white, image_alpha * arg2);\n    draw_sprite_ext(sprite_index, image_index, x - __xdirB, y - __ydirB, image_xscale, image_yscale, image_angle, c_white, image_alpha * arg2);\n    gpu_set_fog(false, c_white, 0, 0);\n}\n",
    "draw_circular_bar": "function draw_circular_bar(arg0, arg1, arg2, arg3, arg4, arg5, arg6, arg7, arg8)\n{\n    if (argument2 > 0)\n    {\n        var numberofsections = 60;\n        var sizeofsection = 360 / numberofsections;\n        var val = (argument2 / argument3) * numberofsections;\n        \n        if (val > 1)\n        {\n            piesurface = surface_create(argument5 * 2, argument5 * 2);\n            draw_set_colour(argument4);\n            draw_set_alpha(argument6);\n            surface_set_target(piesurface);\n            draw_clear_alpha(c_blue, 0.7);\n            draw_clear_alpha(c_black, 0);\n            draw_primitive_begin(pr_trianglefan);\n            draw_vertex(argument5, argument5);\n            \n            for (var i = 0; i <= val; i++)\n            {\n                var len = (i * sizeofsection) + 90;\n                var tx = lengthdir_x(argument5, len);\n                var ty = lengthdir_y(argument5, len);\n                draw_vertex(argument5 + tx, argument5 + ty);\n            }\n            \n            draw_primitive_end();\n            draw_set_alpha(1);\n            draw_set_blend_mode(bm_subtract);\n            draw_set_colour(c_black);\n            d_circle(argument5 - 1, argument5 - 1, argument5 - argument7, false);\n            draw_set_blend_mode(bm_normal);\n            surface_reset_target();\n            \n            if (arg8)\n                draw_set_blend_mode(bm_add);\n            \n            draw_surface(piesurface, argument0 - argument5, argument1 - argument5);\n            draw_set_blend_mode(bm_normal);\n            surface_free(piesurface);\n        }\n    }\n}\n",
