    "scr_initialize_charnames": "function scr_initialize_charnames()\n{\n    global.lcharname = stringsetloc(\"Kris\", \"scr_gamestart_slash_scr_gamestart_gml_396_0\");\n    global.charname[0] = stringsetloc(\" \", \"scr_gamestart_slash_scr_gamestart_gml_101_0_b\");\n    global.charname[1] = stringsetloc(\"Kris\", \"scr_gamestart_slash_scr_gamestart_gml_99_0\");\n    global.charname[2] = stringsetloc(\"Susie\", \"scr_gamestart_slash_scr_gamestart_gml_100_0\");\n    global.charname[3] = stringsetloc(\"Ralsei\", \"scr_gamestart_slash_scr_gamestart_gml_101_0\");\n    global.charname[4] = stringsetloc(\"Noelle\", \"scr_gamestart_slash_scr_gamestart_gml_105_0\");\n}\n",
    "scr_sideb_get_phase": "function scr_sideb_get_phase()\n{\n    var phase = 0;\n    \n    if (global.flag[916] == 0)\n    {\n        if (global.flag[915] > 0 && global.flag[915] < 4)\n            phase = 1;\n        \n        if (global.flag[915] >= 4 && global.flag[915] < 7)\n            phase = 2;\n        \n        if (global.flag[915] >= 7 && global.flag[915] < 20)\n            phase = 3;\n        \n        if (global.flag[915] >= 20)\n            phase = 4;\n    }\n    \n    return phase;\n}\n\nfunction scr_sideb_active()\n{\n    return scr_sideb_get_phase() >= 3;\n}\n",
