    "scr_setup_wind": "function scr_setup_wind(arg0, arg1)\n{\n    with (obj_plat_windcontroller_new)\n        instance_destroy();\n    \n    with (obj_plat_wind)\n        instance_destroy();\n    \n    if (arg0 > 0 && global.flag[arg0] == 0)\n        global.flag[arg0] = arg1 + 2;\n    \n    var wc = instance_create(0, 0, obj_plat_windcontroller_new);\n    var wind = instance_create(0, 0, obj_plat_wind);\n    wind.image_xscale = room_width / wind.sprite_width;\n    wind.image_yscale = room_height / wind.sprite_height;\n    wind.y += 0.5 * wind.sprite_height;\n    \n    if (arg0 <= 0)\n    {\n        wc.winddirection = arg1;\n        \n        with (wc)\n            change_wind_direction(arg1, 0);\n    }\n    \n    return wc;\n}\n\nfunction scr_vfx_windboost(arg0 = -1, arg1 = 20)\n{\n    if (arg0 == -1)\n    {\n        with (obj_plat_windcontroller_new)\n        {\n            arg0 = winddirection;\n            break;\n        }\n    }\n    \n    if (arg0 >= 0)\n    {\n        var xx = camerax();\n        var yy = cameray();\n        var ww = camerax() + camerawidth();\n        var hh = cameray() + cameraheight();\n        \n        for (var i = 0; i < arg1; i++)\n        {\n            var dir = arg0;\n            var xxx = random_range(xx, ww);\n            var yyy = random_range(yy, hh);\n            var _len = irandom(sprite_height / 2) * choose(-1, 1);\n            \n            with (instance_create_depth(xxx, yyy, 11000, obj_plat_wind_particle))\n            {\n                direction = dir;\n                scr_doom(self, 80);\n                speed = 10 + irandom(20);\n                startspeed = speed;\n                _len = 2 + irandom(8);\n                image_angle = dir;\n                image_alpha = 0;\n                scr_lerpvar(\"image_alpha\", 0, 1, 8);\n                image_xscale = 2 * random_range(2, 8);\n                image_yscale = 2;\n            }\n        }\n    }\n}\n",
    "scr_configure_platmode_act": "function scr_configure_platmode_act(arg0, arg1, arg2, arg3)\n{\n    var helper = instance_create(x, y, obj_plat_targethelper);\n    helper.owner = self;\n    helper.effect = arg0;\n    helper.char = arg1;\n    helper.objectname = arg2;\n    helper.description = arg3;\n    \n    if (!variable_instance_exists(id, \"__plat_acts\"))\n        __plat_acts = [];\n    \n    array_push(__plat_acts, helper);\n    return helper;\n}\n\nfunction scr_set_platmode_act_active(arg0, arg1 = \"*\")\n{\n    if (variable_instance_exists(id, \"__plat_acts\"))\n    {\n        for (var i = 0; i < array_length(__plat_acts); i++)\n        {\n            if (arg1 == \"*\" || __plat_acts.char == arg1)\n                active = arg0;\n        }\n    }\n}\n\nfunction scr_destroy_platmode_act()\n{\n    if (variable_instance_exists(id, \"__plat_acts\"))\n    {\n        for (var i = 0; i < array_length(__plat_acts); i++)\n        {\n            with (__plat_acts[i])\n                instance_destroy();\n        }\n    }\n}\n",
    "scr_wind_direction": "function scr_wind_direction()\n{\n    with (obj_plat_windcontroller_new)\n        return winddirection;\n    \n    return -1;\n}\n\nfunction scr_wind_strength()\n{\n    with (obj_plat_windcontroller_new)\n        return strength;\n    \n    return 0;\n}\n",
    "scr_plat_barrier": "function scr_plat_barrier_enable()\n{\n    with (instance_create(0, 0, obj_plat_barrier))\n        appear();\n}\n\nfunction scr_plat_barrier_disable()\n{\n    with (obj_plat_barrier)\n        disappear();\n}\n\nfunction scr_plat_barrier_toggle_vertical(arg0)\n{\n    with (obj_plat_barrier)\n        toggle_vertical(arg0);\n}\n",
    "c_msgfunc": "function c_msgfunc(arg0, arg1 = -1)\n{\n    c_cmd_x(\"msgcmd\", \"customfunc\", arg1, arg0, 0, 0, 0);\n}\n",
    "scr_marker": "function scr_marker(arg0, arg1, arg2)\n{\n    thismarker = instance_create(arg0, arg1, obj_marker);\n    \n    with (thismarker)\n    {\n        sprite_index = arg2;\n        image_speed = 0;\n    }\n    \n    return thismarker;\n}\n",
    "scr_make_fixed_size": "function scr_make_fixed_size(arg0 = -1, arg1 = -1)\n{\n    if (arg0 != -1)\n        image_xscale = arg0 / sprite_get_width(sprite_index);\n    \n    if (arg1 != -1)\n        image_yscale = arg1 / sprite_get_height(sprite_index);\n}\n",
    "scr_makemarker_fromstruct": "function scr_makemarker_fromstruct(arg0, arg1 = false)\n{\n    var _marker;\n    \n    if (arg1 == 2)\n    {\n        _marker = instance_create(arg0.x, arg0.y, obj_marker_fancy);\n        \n        with (_marker)\n        {\n            sprite_index = arg0.sprite_index;\n            image_speed = 0;\n        }\n    }\n    else if (arg1)\n    {\n        _marker = scr_marker_fancy(arg0.x, arg0.y, arg0.sprite_index);\n    }\n    else\n    {\n        _marker = scr_marker(arg0.x, arg0.y, arg0.sprite_index);\n    }\n    \n    with (_marker)\n    {\n        scr_spritematch(arg0);\n        scr_depth();\n    }\n    \n    return _marker;\n}\n",
    "scr_losechar": "function scr_losechar()\n{\n    global.char[2] = 0;\n    global.char[1] = 0;\n    \n    with (obj_darkcontroller)\n    {\n        chartotal = 0;\n        havechar[0] = 0;\n        havechar[1] = 0;\n        havechar[2] = 0;\n        havechar[3] = 0;\n        \n        for (i = 0; i < 3; i += 1)\n        {\n            global.faceaction[i] = 0;\n            \n            if (global.char[i] != 0)\n                chartotal += 1;\n            \n            if (global.char[i] == 1)\n            {\n                havechar[0] = 1;\n                charpos[0] = i;\n            }\n            \n            if (global.char[i] == 2)\n            {\n                havechar[1] = 1;\n                charpos[1] = i;\n            }\n            \n            if (global.char[i] == 3)\n            {\n                havechar[2] = 1;\n                charpos[2] = i;\n            }\n            \n            if (global.char[i] == 4)\n            {\n                havechar[3] = 1;\n                charpos[3] = i;\n            }\n        }\n    }\n    \n    global.submenu = 0;\n    global.charselect = -1;\n    \n    for (i = 0; i < 36; i += 1)\n        global.submenucoord[i] = 0;\n}\n",
    "c_sel_facing": "function c_sel_facing(arg0, arg1)\n{\n    c_cmd(\"select\", arg0, 0, 0, 0);\n    c_cmd(\"facing\", arg1, 0, 0, 0);\n}\n",
    "c_walkdirect": "function c_walkdirect(arg0, arg1, arg2)\n{\n    c_cmd(\"walkdirect\", arg0, arg1, arg2, 0);\n}\n",
