    "scr_funnytext_init": "function scr_funnytext_init()\n{\n    global.writerobj[argument0] = obj_funnytext;\n    global.writerobjx[argument0] = argument1;\n    global.writerobjy[argument0] = argument2;\n    global.writerimg[argument0] = argument3;\n    global.writerobjsettinga[argument0] = argument4;\n    global.writerobjsettingb[argument0] = argument5;\n}\n\nfunction scr_funnytext_init_sounds()\n{\n    global.funnytext_sounds = [scr_funnytext_new_sound(snd_ftext_bounce, [spr_funnytext_dump_her])];\n}\n\nfunction scr_funnytext_get_sound(arg0)\n{\n    if (!variable_global_exists(\"funnytext_sounds\"))\n        scr_funnytext_init_sounds();\n    \n    var sound_file = -4;\n    \n    for (var i = 0; i < array_length(global.funnytext_sounds); i++)\n    {\n        var sprite_list = global.funnytext_sounds[i][1];\n        \n        for (var j = 0; j < array_length(sprite_list); j++)\n        {\n            var sprite = scr_84_get_sprite(sprite_list[j]);\n            \n            if (arg0 != sprite)\n                continue;\n            \n            sound_file = global.funnytext_sounds[i][0];\n            break;\n        }\n        \n        if (sound_file != -4)\n            break;\n    }\n    \n    return sound_file;\n}\n\nfunction scr_funnytext_new_sound(arg0, arg1)\n{\n    var sound_file = arg0;\n    var sprite_list = [];\n    \n    for (var i = 0; i < array_length(arg1); i++)\n        sprite_list[array_length(sprite_list)] = sprite_get_name(arg1[i]);\n    \n    var funnytext_sound = [];\n    funnytext_sound[0] = sound_file;\n    funnytext_sound[1] = sprite_list;\n    return funnytext_sound;\n}\n",
    "ease_inout_quint": "function ease_inout_quint(arg0, arg1, arg2, arg3)\n{\n    arg0 /= (arg3 * 0.5);\n    \n    if (arg0 < 1)\n        return (arg2 * 0.5 * power(arg0, 5)) + arg1;\n    \n    return (arg2 * 0.5 * (power(arg0 - 2, 5) + 2)) + arg1;\n}\n",
    "ease_inout_quart": "function ease_inout_quart(arg0, arg1, arg2, arg3)\n{\n    arg0 /= (arg3 * 0.5);\n    \n    if (arg0 < 1)\n        return (arg2 * 0.5 * power(arg0, 4)) + arg1;\n    \n    return (-arg2 * 0.5 * (power(arg0 - 2, 4) - 2)) + arg1;\n}\n",
    "ease_inout_expo": "function ease_inout_expo(arg0, arg1, arg2, arg3)\n{\n    arg0 /= (arg3 * 0.5);\n    \n    if (arg0 < 1)\n        return (arg2 * 0.5 * power(2, 10 * (arg0 - 1))) + arg1;\n    \n    arg0 -= 1;\n    return (arg2 * 0.5 * (-power(2, -10 * arg0) + 2)) + arg1;\n}\n",
    "ease_inout_elastic": "function ease_inout_elastic(arg0, arg1, arg2, arg3)\n{\n    var _s = 1.70158;\n    var _p = 0;\n    var _a = arg2;\n    \n    if (arg0 == 0 || _a == 0)\n        return arg1;\n    \n    arg0 /= (arg3 * 0.5);\n    \n    if (arg0 == 2)\n        return arg1 + arg2;\n    \n    if (!_p)\n        _p = arg3 * 0.44999999999999996;\n    \n    if (_a < abs(arg2))\n    {\n        _a = arg2;\n        _s = _p * 0.25;\n    }\n    else\n    {\n        _s = (_p / (2 * pi)) * arcsin(arg2 / _a);\n    }\n    \n    if (arg0 < 1)\n        return (-0.5 * (_a * power(2, 10 * --arg0) * sin((((arg0 * arg3) - _s) * (2 * pi)) / _p))) + arg1;\n    \n    return (_a * power(2, -10 * --arg0) * sin((((arg0 * arg3) - _s) * (2 * pi)) / _p) * 0.5) + arg2 + arg1;\n}\n",
    "ease_inout_cubic": "function ease_inout_cubic(arg0, arg1, arg2, arg3)\n{\n    arg0 /= (arg3 * 0.5);\n    \n    if (arg0 < 1)\n        return (arg2 * 0.5 * power(arg0, 3)) + arg1;\n    \n    return (arg2 * 0.5 * (power(arg0 - 2, 3) + 2)) + arg1;\n}\n",
    "ease_inout_circ": "function ease_inout_circ(arg0, arg1, arg2, arg3)\n{\n    arg0 /= (arg3 * 0.5);\n    \n    if (arg0 < 1)\n        return (arg2 * 0.5 * (1 - sqrt(1 - (arg0 * arg0)))) + arg1;\n    \n    arg0 -= 2;\n    return (arg2 * 0.5 * (sqrt(1 - (arg0 * arg0)) + 1)) + arg1;\n}\n",
    "ease_inout_bounce": "function ease_inout_bounce(arg0, arg1, arg2, arg3)\n{\n    if (arg0 < (arg3 * 0.5))\n        return (ease_in_bounce(arg0 * 2, 0, arg2, arg3) * 0.5) + arg1;\n    \n    return (ease_out_bounce((arg0 * 2) - arg3, 0, arg2, arg3) * 0.5) + (arg2 * 0.5) + arg1;\n}\n",
    "ease_inout_back": "function ease_inout_back(arg0, arg1, arg2, arg3)\n{\n    var _s = 1.70158;\n    arg0 /= arg3;\n    arg0 *= 2;\n    \n    if (arg0 < 1)\n    {\n        _s *= 1.525;\n        return (arg2 * 0.5 * (arg0 * arg0 * (((_s + 1) * arg0) - _s))) + arg1;\n    }\n    \n    arg0 -= 2;\n    _s *= 1.525;\n    return (arg2 * 0.5 * ((arg0 * arg0 * (((_s + 1) * arg0) + _s)) + 2)) + arg1;\n}\n",
    "ease_out_quint": "function ease_out_quint(arg0, arg1, arg2, arg3)\n{\n    return (arg2 * (power((arg0 / arg3) - 1, 5) + 1)) + arg1;\n}\n",
    "ease_out_quart": "function ease_out_quart(arg0, arg1, arg2, arg3)\n{\n    return (-arg2 * (power((arg0 / arg3) - 1, 4) - 1)) + arg1;\n}\n",
    "ease_out_expo": "function ease_out_expo(arg0, arg1, arg2, arg3)\n{\n    return (arg2 * (-power(2, (-10 * arg0) / arg3) + 1)) + arg1;\n}\n",
    "ease_out_elastic": "function ease_out_elastic(arg0, arg1, arg2, arg3)\n{\n    var _s = 1.70158;\n    var _p = 0;\n    var time = arg0;\n    var start = arg1;\n    var change = arg2;\n    var duration = arg3;\n    \n    if (time == 0 || change == 0)\n        return start;\n    \n    time /= duration;\n    \n    if (time == 1)\n        return start + arg2;\n    \n    if (!_p)\n        _p = duration * 0.3;\n    \n    if (change < abs(arg2))\n    {\n        change = arg2;\n        _s = _p * 0.25;\n    }\n    else\n    {\n        _s = (_p / (2 * pi)) * arcsin(arg2 / change);\n    }\n    \n    return (change * power(2, -10 * time) * sin((((time * duration) - _s) * (2 * pi)) / _p)) + arg2 + start;\n}\n",
    "ease_out_cubic": "function ease_out_cubic(arg0, arg1, arg2, arg3)\n{\n    return (arg2 * (power((arg0 / arg3) - 1, 3) + 1)) + arg1;\n}\n",
    "ease_out_circ": "function ease_out_circ(arg0, arg1, arg2, arg3)\n{\n    arg0 = (arg0 / arg3) - 1;\n    return (arg2 * sqrt(1 - (arg0 * arg0))) + arg1;\n}\n",
    "ease_out_bounce": "function ease_out_bounce(arg0, arg1, arg2, arg3)\n{\n    arg0 /= arg3;\n    \n    if (arg0 < 0.36363636363636365)\n    {\n        return (arg2 * (7.5625 * arg0 * arg0)) + arg1;\n    }\n    else if (arg0 < 0.7272727272727273)\n    {\n        arg0 -= 0.5454545454545454;\n        return (arg2 * ((7.5625 * arg0 * arg0) + 0.75)) + arg1;\n    }\n    else if (arg0 < 0.9090909090909091)\n    {\n        arg0 -= 0.8181818181818182;\n        return (arg2 * ((7.5625 * arg0 * arg0) + 0.9375)) + arg1;\n    }\n    else\n    {\n        arg0 -= 0.9545454545454546;\n        return (arg2 * ((7.5625 * arg0 * arg0) + 0.984375)) + arg1;\n    }\n}\n",
    "ease_out_back": "function ease_out_back(arg0, arg1, arg2, arg3)\n{\n    var _s = 1.70158;\n    arg0 = (arg0 / arg3) - 1;\n    return (arg2 * ((arg0 * arg0 * (((_s + 1) * arg0) + _s)) + 1)) + arg1;\n}\n",
    "ease_in_quint": "function ease_in_quint(arg0, arg1, arg2, arg3)\n{\n    return (arg2 * power(arg0 / arg3, 5)) + arg1;\n}\n",
    "ease_in_quart": "function ease_in_quart(arg0, arg1, arg2, arg3)\n{\n    return (arg2 * power(arg0 / arg3, 4)) + arg1;\n}\n",
