    "scr_blconskip": "function scr_blconskip(arg0)\n{\n    if (arg0 >= 0)\n    {\n        if (button1_p() && talktimer > arg0)\n            talktimer = talkmax;\n        \n        talktimer++;\n        \n        if (talktimer >= talkmax)\n        {\n            with (obj_writer)\n                instance_destroy();\n            \n            if (i_ex(obj_balloon_queue))\n                msgset_fromqueue();\n            else\n                global.mnfight = 1.5;\n        }\n    }\n    else if (arg0 == -1)\n    {\n        if (!instance_exists(obj_writer))\n        {\n            if (i_ex(obj_balloon_queue))\n                msgset_fromqueue();\n            else\n                global.mnfight = 1.5;\n        }\n    }\n    else if (arg0 == -2)\n    {\n        talktimer++;\n        \n        if (talktimer > 15)\n            talktimer = talkmax;\n        \n        if (talktimer >= talkmax)\n        {\n            with (obj_writer)\n                instance_destroy();\n            \n            if (i_ex(obj_balloon_queue))\n                msgset_fromqueue();\n            else\n                global.mnfight = 1.5;\n        }\n    }\n}\n",
    "scr_messagepriority": "function scr_messagepriority(arg0)\n{\n    if (i_ex(obj_battlecontroller))\n    {\n        if (obj_battlecontroller.messagepriority < arg0)\n        {\n            obj_battlecontroller.messagepriority = arg0;\n            return true;\n        }\n        else\n        {\n            return false;\n        }\n    }\n    else\n    {\n        return false;\n    }\n}\n",
    "scr_monster_make_tired": "function scr_monster_make_tired(arg0)\n{\n    if (global.monsterstatus[arg0] == 0)\n    {\n        __tiredwriter = instance_create(global.monsterx[arg0], (global.monstery[arg0] - (global.hittarget[arg0] * 20)) + 20, obj_dmgwriter);\n        __tiredwriter.type = 13;\n        global.hittarget[arg0] += 1;\n        snd_play_x(snd_spellcast, 0.5, 0.9);\n    }\n    \n    global.monstercomment[arg0] = stringsetloc(\"(Tired)\", \"scr_monster_make_tired_slash_scr_monster_make_tired_gml_1_0\");\n    global.monsterstatus[arg0] = 1;\n}\n",
    "scr_enemyhurt_tired_after_damage": "function scr_enemyhurt_tired_after_damage(arg0)\n{\n    if (global.monsterhp[myself] <= (global.monstermaxhp[myself] * arg0))\n        scr_monster_make_tired(myself);\n}\n",
    "scr_attackphase": "function scr_attackphase()\n{\n    with (obj_battlecontroller)\n    {\n        techwon = 0;\n        \n        if (scr_monsterpop() == 0)\n            techwon = 1;\n        \n        if (techwon == 1)\n            scr_wincombat();\n        \n        if (techwon == 0)\n        {\n            for (__hiti = 0; __hiti < 3; __hiti++)\n                global.hittarget[__hiti] = 0;\n            \n            fightphase = 1;\n            global.charturn = 3;\n            \n            if (global.charaction[0] == 4 || global.charaction[0] == 2)\n                fightphase = 0;\n            \n            if (global.charaction[1] == 4 || global.charaction[1] == 2)\n                fightphase = 0;\n            \n            if (global.charaction[2] == 4 || global.charaction[2] == 2)\n                fightphase = 0;\n            \n            if (global.myfight == 4)\n                fightphase = 1;\n            \n            if (fightphase == 1)\n            {\n                global.myfight = 1;\n                instance_create(xx + 2, yy + 365, obj_attackpress);\n            }\n            else\n            {\n                global.myfight = 4;\n                instance_create(0, 0, obj_spellphase);\n            }\n        }\n    }\n}\n",
    "scr_recruited_all": "function scr_recruited_all()\n{\n    var recruited_all = true;\n    var min_chapter = 1;\n    var max_chapter = global.chapter + 1;\n    \n    for (var i = min_chapter; i < max_chapter; i++)\n    {\n        recruited_all = scr_recruited_all_in_chapter(i);\n        \n        if (!recruited_all)\n            break;\n    }\n    \n    return recruited_all;\n}\n\nfunction scr_recruited_all_previous()\n{\n    var recruited_all = true;\n    var min_chapter = 1;\n    var max_chapter = global.chapter;\n    \n    for (var i = min_chapter; i < max_chapter; i++)\n    {\n        recruited_all = scr_recruited_all_in_chapter(i);\n        \n        if (!recruited_all)\n            break;\n    }\n    \n    return recruited_all;\n}\n\nfunction scr_recruited_all_in_chapter(arg0)\n{\n    var chapter = arg0;\n    var recruit_data = scr_get_chapter_recruit_data(chapter);\n    var all_recruited = true;\n    \n    for (var i = 0; i < array_length_1d(recruit_data); i++)\n    {\n        if (global.flag[600 + recruit_data[i]] < 1)\n        {\n            all_recruited = false;\n            break;\n        }\n    }\n    \n    return all_recruited;\n}\n\nfunction scr_get_chapter_recruit_data(arg0)\n{\n    var chapter = arg0;\n    var recruit_ids = [];\n    \n    if (chapter == 1)\n        recruit_ids = [5, 6, 11, 13, 14, 15, 22, 23];\n    \n    if (chapter == 2)\n        recruit_ids = [30, 31, 32, 33, 34, 35, 36, 40, 42, 44];\n    \n    if (chapter == 3)\n        recruit_ids = [54, 55, 56, 57, 58, 59, 60, 61];\n    \n    if (chapter == 4)\n        recruit_ids = [62, 63, 64, 65, 66, 67, 68, 69];\n    \n    if (chapter == 5)\n        recruit_ids = [70, 71, 72, 73, 74, 75, 76, 77];\n    \n    return recruit_ids;\n}\n\nfunction scr_get_total_recruits(arg0)\n{\n    var totalrecruits = 0;\n    var chapter = arg0;\n    var recruit_data = scr_get_chapter_recruit_data(chapter);\n    \n    for (var i = 0; i < array_length_1d(recruit_data); i++)\n    {\n        if (global.flag[600 + recruit_data[i]] == 1)\n            totalrecruits++;\n    }\n    \n    return totalrecruits;\n}\n",
