    "scr_oflash_tower": "function scr_oflash_tower()\n{\n    _oflash = instance_create(x, y, obj_oflash_tower);\n    _oflash.image_xscale = image_xscale;\n    _oflash.image_speed = 0;\n    _oflash.image_index = image_index;\n    _oflash.image_yscale = image_yscale;\n    _oflash.sprite_index = sprite_index;\n    _oflash.depth = depth - 1;\n    _oflash.target = id;\n    return _oflash;\n}\n",
    "scr_shakeobj_tower": "function scr_shakeobj_tower()\n{\n    var _shakeobj = instance_create(x, y, obj_shakeobj_tower);\n    _shakeobj.target = id;\n    \n    if (argument_count >= 1)\n    {\n        if (i_ex(argument0))\n            _shakeobj.target = argument0;\n    }\n    \n    if (argument_count >= 2)\n    {\n        if (argument1 != -1)\n            _shakeobj.shakeamt = argument1;\n    }\n    \n    if (argument_count >= 3)\n    {\n        if (argument2 != -1)\n            _shakeobj.shakereduct = argument2;\n    }\n    \n    with (_shakeobj)\n        event_user(0);\n}\n",
    "scr_afterimage_cut_half_tower": "function scr_afterimage_cut_half_tower()\n{\n    afterimage = instance_create(x, y, obj_afterimage_cut_half_tower);\n    afterimage.sprite_index = sprite_index;\n    afterimage.image_index = image_index;\n    afterimage.image_blend = image_blend;\n    afterimage.image_speed = 0;\n    afterimage.depth = depth;\n    afterimage.image_xscale = image_xscale;\n    afterimage.image_yscale = image_yscale;\n    afterimage.image_angle = image_angle;\n    \n    with (afterimage)\n        event_user(0);\n    \n    return afterimage;\n}\n",
