    "scr_whiteflash": "function scr_whiteflash(arg0, arg1)\n{\n    var timer = instance_create(x, y, obj_whiteflash);\n    timer.obj = arg0;\n    timer.alarm[0] = arg1;\n    \n    with (arg0)\n        flash_white = true;\n    \n    return timer;\n}\n",
    "scr_flower_die": "function scr_flower_die(arg0 = 2, arg1 = 6, arg2 = 5, arg3 = 0, arg4 = true)\n{\n    if (arg0 >= 3)\n    {\n        with (instance_create_depth(x, y, depth, obj_flowerdie_big))\n        {\n            sprite_index = other.sprite_index;\n            image_index = other.image_index;\n            image_angle = other.image_angle;\n            image_xscale = other.image_xscale;\n            image_yscale = other.image_yscale;\n            image_speed = other.image_speed;\n            coindrops = arg3;\n            use_image_speed = arg4;\n            \n            if (arg0 == 4)\n            {\n                wall_smash = true;\n                \n                if (other.image_xscale < 0)\n                    image_angle += 180;\n            }\n        }\n    }\n    else\n    {\n        with (instance_create_depth(x, y, depth, obj_flowerdie))\n        {\n            speed = arg2;\n            \n            if (arg0 == 1)\n            {\n                sprite_index = spr_falling_petal;\n                image_blend = c_gray;\n                image_xscale = 2;\n                image_yscale = 2;\n            }\n            \n            amount = arg1;\n            size = arg0;\n        }\n        \n        if (arg0 == 1)\n            instance_create_depth(x, y, depth - 5, obj_flowerdie_mini);\n        \n        if (arg3 == 0)\n            exit;\n        \n        scr_plat_makecoins(x, y, -coindrops, 90, 90, 8, 4, depth);\n        coindrops = 0;\n    }\n}\n",
    "scr_plat_create_stunspark": "function scr_plat_create_stunspark()\n{\n    var spark = instance_create(random_range(bbox_left, bbox_right), random_range(bbox_top, bbox_bottom), obj_marker);\n    \n    with (spark)\n    {\n        sprite_index = spr_plat_rudebuster_sparks;\n        image_speed = 0;\n        depth = other.depth - 1;\n        image_index = irandom_range(0, 3);\n        image_angle = random_range(0, 360);\n        scr_shakeobj();\n        scr_doom(self, 2);\n    }\n}\n",
    "scr_limitval": "function scr_limitval_lower(arg0 = id, arg1, arg2, arg3 = -1)\n{\n    var ____limiter = instance_create(x, y, obj_limit_val);\n    ____limiter.limittype = 0;\n    ____limiter.target = arg0;\n    ____limiter.variablename = arg1;\n    ____limiter.vallimit = arg2;\n    ____limiter.lifetime = arg3;\n    return ____limiter;\n}\n\nfunction scr_limitval_upper(arg0 = id, arg1, arg2, arg3 = -1)\n{\n    var ____limiter = instance_create(x, y, obj_limit_val);\n    ____limiter.limittype = 1;\n    ____limiter.target = arg0;\n    ____limiter.variablename = arg1;\n    ____limiter.vallimit2 = arg2;\n    ____limiter.lifetime = arg3;\n    return ____limiter;\n}\n\nfunction scr_limitval_clamp(arg0 = id, arg1, arg2, arg3, arg4 = -1)\n{\n    var ____limiter = instance_create(x, y, obj_limit_val);\n    ____limiter.target = arg0;\n    ____limiter.limittype = 2;\n    ____limiter.variablename = arg1;\n    ____limiter.vallimit = arg2;\n    ____limiter.vallimit2 = arg3;\n    ____limiter.lifetime = arg4;\n    return ____limiter;\n}\n",
    "c_walkto_straight": "function c_walkto_straight(arg0 = \n{\n    x: 0,\n    y: 0\n}, arg1 = \n{\n    x: 40,\n    y: 40\n}, arg2 = 4, arg3 = 0, arg4 = \"\")\n{\n    var disth = max(round(abs(arg0.x - arg1.x) / arg2), 1);\n    var distv = max(round(abs(arg0.y - arg1.y) / arg2), 1);\n    \n    if (arg3 == 0)\n    {\n        if (distv > 0)\n            c_walkdirect(arg0.x, arg1.y, distv);\n        \n        if (disth > 0)\n            c_delaywalkdirect(distv + 1, arg1.x, arg1.y, disth);\n    }\n    else\n    {\n        if (distv > 0)\n            c_walkdirect(arg1.x, arg0.y, disth);\n        \n        if (disth > 0)\n            c_delaywalkdirect(disth + 1, arg1.x, arg1.y, distv);\n    }\n    \n    var toface = \"-1\";\n    \n    if (is_string(arg4))\n    {\n        if (arg4 == \"u\" || arg4 == \"U\" || arg4 == \"r\" || arg4 == \"R\" || arg4 == \"d\" || arg4 == \"D\" || arg4 == \"l\" || arg4 == \"L\")\n            toface = string_lower(arg4);\n    }\n    else\n    {\n        switch (arg4)\n        {\n            case 0:\n                toface = \"d\";\n                break;\n            \n            case 1:\n                toface = \"r\";\n                break;\n            \n            case 2:\n                toface = \"u\";\n                break;\n            \n            case 3:\n                toface = \"l\";\n                break;\n        }\n    }\n    \n    if (toface != \"-1\")\n        c_delayfacing(disth + distv + 1, toface);\n    \n    return disth + distv;\n}\n\nfunction c_walktostraight_list(arg0, arg1 = [], arg2 = \"-1\", arg3 = 4)\n{\n    var totalwait = 0;\n    \n    for (var i = 0; i < array_length(arg1); i++)\n    {\n        var pref = \"h\";\n        \n        if (variable_struct_exists(arg1[i], \"pref\"))\n        {\n            if ((is_string(arg1[i].pref) && (arg1[i].pref == \"v\" || arg1[i].pref == \"V\")) || arg1[i].pref == 0)\n                pref = \"v\";\n        }\n        \n        var st = arg0;\n        \n        if (i > 0)\n            st = arg1[i - 1].inst;\n        \n        var ed = arg1[i].inst;\n        var thisspd = arg3;\n        \n        if (variable_struct_exists(arg1[i], \"spd\"))\n            thisspd = arg1[i].spd;\n        \n        var disth = max(round(abs(st.x - ed.x) / thisspd), 0);\n        var distv = max(round(abs(st.y - ed.y) / thisspd), 0);\n        \n        if (pref == \"h\")\n        {\n            if (disth > 0)\n            {\n                if (totalwait == 0)\n                    c_walkdirect(ed.x, st.y, disth);\n                else\n                    c_delaywalkdirect(totalwait, ed.x, st.y, disth);\n                \n                totalwait += disth;\n                show_debug_message_concat(i, \", distv=\", disth);\n            }\n            \n            if (distv > 0)\n            {\n                if (totalwait == 0)\n                    c_walkdirect(ed.x, ed.y, distv);\n                else\n                    c_delaywalkdirect(totalwait, ed.x, ed.y, distv);\n                \n                totalwait += distv;\n            }\n        }\n        else\n        {\n            if (distv > 0)\n            {\n                if (totalwait == 0)\n                    c_walkdirect(st.x, ed.y, distv);\n                else\n                    c_delaywalkdirect(totalwait, st.x, ed.y, distv);\n                \n                totalwait += distv;\n            }\n            \n            if (disth > 0)\n            {\n                if (totalwait == 0)\n                    c_walkdirect(ed.x, ed.y, disth);\n                else\n                    c_delaywalkdirect(totalwait, ed.x, ed.y, disth);\n                \n                totalwait += disth;\n            }\n        }\n    }\n    \n    var toface = \"-1\";\n    \n    if (is_string(arg2))\n    {\n        if (arg2 == \"u\" || arg2 == \"U\" || arg2 == \"r\" || arg2 == \"R\" || arg2 == \"d\" || arg2 == \"D\" || arg2 == \"l\" || arg2 == \"L\")\n            toface = string_lower(arg2);\n    }\n    else\n    {\n        switch (arg2)\n        {\n            case 0:\n                toface = \"d\";\n                break;\n            \n            case 1:\n                toface = \"r\";\n                break;\n            \n            case 2:\n                toface = \"u\";\n                break;\n            \n            case 3:\n                toface = \"l\";\n                break;\n        }\n    }\n    \n    if (toface != \"-1\")\n        c_delayfacing(totalwait + 1, toface);\n    \n    return totalwait;\n}\n",
