    "scr_emote": "function scr_emote()\n{\n    __dmult = 1 + global.darkzone;\n    __emotebubble = instance_create(x, y - 15, obj_excblcon);\n    __emotebubble.alarm[0] = argument[1];\n    __emotebubble.image_xscale = __dmult;\n    __emotebubble.image_yscale = __dmult;\n    __emotexoff = 0;\n    __emoteyoff = 0;\n    __anchorx = sprite_get_xoffset(sprite_index);\n    \n    if (argument[0] == \"!\")\n    {\n        __emotebubble.sprite_index = spr_exc;\n        __emotebubble.y = y - (10 * __dmult);\n        __emotexoff = 10 * __dmult;\n    }\n    \n    if (argument[0] == \"?\")\n    {\n        __emotebubble.sprite_index = spr_emote_questionmark;\n        __emotebubble.y = y - (10 * __dmult);\n        __emotexoff = 10 * __dmult;\n    }\n    \n    if (argument[0] == \"...\")\n    {\n        __emotebubble.sprite_index = spr_emote_ellipsis;\n        __emotebubble.y = y - (10 * __dmult);\n        __emotexoff = 10 * __dmult;\n    }\n    \n    if (argument[0] == \"note\")\n    {\n        __emotebubble.sprite_index = spr_musblc;\n        __emotebubble.y = y - (10 * __dmult);\n        __emotexoff = 10 * __dmult;\n    }\n    \n    if (argument_count >= 3)\n        __emotexoff = argument[2];\n    \n    if (argument_count >= 4)\n        __emoteyoff = argument[3];\n    \n    __emotebubble.y += __emoteyoff;\n    \n    if (image_xscale > 0)\n        __emotebubble.x = (((x - (__anchorx * image_xscale)) + ((sprite_width / 2) * sign(image_xscale))) - (__emotebubble.sprite_width / 2)) + __emotexoff;\n    else\n        __emotebubble.x = ((x + (__anchorx * image_xscale)) - ((sprite_width / 2) * sign(image_xscale)) - (__emotebubble.sprite_width / 2)) + __emotexoff;\n}\n",
    "scr_shakeobj_ext": "function scr_shakeobj_ext()\n{\n    var _shakeobj = instance_create(x, y, obj_shakeobj_ext);\n    _shakeobj.target = id;\n    \n    if (argument_count >= 1)\n    {\n        if (i_ex(argument0))\n            _shakeobj.target = argument0;\n    }\n    \n    if (argument_count >= 2)\n    {\n        if (argument1 != -1)\n            _shakeobj.shakexamt = argument1;\n    }\n    \n    if (argument_count >= 3)\n    {\n        if (argument2 != -1)\n            _shakeobj.shakeyamt = argument2;\n    }\n    \n    if (argument_count >= 4)\n    {\n        if (argument3 != -1)\n            _shakeobj.shakereduct = argument3;\n    }\n    \n    if (argument_count >= 5)\n    {\n        if (argument4 != -1)\n            _shakeobj.shakespeed = argument4;\n    }\n    \n    with (_shakeobj)\n        event_user(0);\n}\n",
    "scr_npcdir": "function scr_npcdir()\n{\n    if (facing == 0)\n        sprite_index = dtsprite;\n    \n    if (facing == 1)\n        sprite_index = rtsprite;\n    \n    if (facing == 2)\n        sprite_index = utsprite;\n    \n    if (facing == 3)\n        sprite_index = ltsprite;\n}\n",
    "scr_tone": "function tone_on(arg0, arg1, arg2, arg3, arg4)\n{\n    shader_replace_simple_set_hook(64);\n    shader_set_uniform_f(shader_get_uniform(shd_tone, \"saturation\"), arg0);\n    shader_set_uniform_f(shader_get_uniform(shd_tone, \"brightness\"), arg1);\n    shader_set_uniform_f(shader_get_uniform(shd_tone, \"tone_factor\"), arg2);\n    shader_set_uniform_f(shader_get_uniform(shd_tone, \"tone_dark\"), color_get_red(arg3) / 255, color_get_green(arg3) / 255, color_get_blue(arg3) / 255);\n    shader_set_uniform_f(shader_get_uniform(shd_tone, \"tone_light\"), color_get_red(arg4) / 255, color_get_green(arg4) / 255, color_get_blue(arg4) / 255);\n}\n\nfunction tone_off()\n{\n    shader_replace_simple_reset_hook();\n}\n",
    "scr_flower_despwn": "function scr_flower_despwn(arg0 = 0)\n{\n    arg0 = 0;\n    hit = 0;\n    \n    with (instance_create_depth(x, y, depth, obj_plat_vfx))\n    {\n        sprite_index = spr_smokepuff;\n        image_speed = 2;\n    }\n    \n    with (instance_create_depth(x, y, 2450, obj_flower_despwn, \n    {\n        image_blend: petal_color\n    }))\n        colored = true;\n    \n    var _spawner = instance_create_depth(x_home, y_home, 2450, obj_flower_spawner, \n    {\n        image_blend: petal_color\n    });\n    _spawner._memory = {};\n    _spawner.image_xscale = image_xscale;\n    _spawner.scale = sign(image_xscale);\n    _spawner.was_onscreen = true;\n    _spawner.colored = true;\n    _spawner.image_yscale = image_yscale;\n    _spawner.image_angle = image_angle;\n    _spawner.obj_index = object_index;\n    _spawner.activate = activate;\n    _spawner.enemy_wave = enemy_wave;\n    var array = __vars;\n    \n    for (var i = 0; i < array_length(array); i++)\n        variable_struct_set(_spawner._memory, array[i], variable_instance_get(id, array[i]));\n    \n    with (_spawner)\n    {\n        obj_index = other.object_index;\n        hp = other.hp;\n    }\n    \n    if (arg0 == 0)\n    {\n        instance_destroy();\n    }\n    else\n    {\n    }\n    \n    exit;\n}\n",
    "scr_floweryactor": "function scr_floweryactor(arg0 = \"flowery_left\", arg1 = \n{\n    x: 0,\n    y: 0\n})\n{\n    actor_count++;\n    fl = array_length(global.cinstance) + 1;\n    fl_actor = instance_create(arg1.x, arg1.y, obj_actor);\n    scr_actor_setup(fl, fl_actor, \"flowery\");\n    \n    with (fl_actor)\n        scr_set_facing_sprites(arg0);\n    \n    fl_actor.sprite_index = fl_actor.dsprite;\n    \n    if (is_struct(arg1))\n    {\n        if (variable_struct_exists(arg1, \"sprite_index\"))\n            fl_actor.sprite_index = arg1.sprite_index;\n    }\n    else\n    {\n        with (arg1)\n        {\n            visible = false;\n            other.fl_actor.sprite_index = sprite_index;\n        }\n    }\n}\n",
    "c_sel_spriteimage": "function c_sel_spriteimage(arg0, arg1, arg2, arg3 = -9999, arg4 = false)\n{\n    c_cmd(\"select\", arg0, 0, 0, 0);\n    c_cmd(\"sprite\", arg1, 0, 0, 0);\n    c_cmd(\"imageindex\", arg2, 0, 0, 0);\n    \n    if (arg3 != -9999)\n    {\n        c_cmd(\"imagespeed\", arg3, 0, 0, 0);\n        \n        if (!arg4)\n            c_cmd(\"autowalk\", arg4, 0, 0, 0);\n    }\n}\n",
