    "draw_text_debug": "function draw_text_debug(arg0, arg1, arg2, arg3 = 0, arg4 = 16777215)\n{\n}\n\nfunction showtxt(arg0, arg1, arg2)\n{\n}\n",
    "scr_keyitemremove": "function scr_keyitemremove(arg0)\n{\n    removed = 0;\n    scr_keyitemcheck(arg0);\n    \n    if (haveit == 1)\n    {\n        loc = 0;\n        skip = 0;\n        \n        if (global.keyitem[0] == arg0 && skip == 0)\n        {\n            loc = 0;\n            skip = 1;\n        }\n        \n        if (global.keyitem[1] == arg0 && skip == 0)\n        {\n            loc = 1;\n            skip = 1;\n        }\n        \n        if (global.keyitem[2] == arg0 && skip == 0)\n        {\n            loc = 2;\n            skip = 1;\n        }\n        \n        if (global.keyitem[3] == arg0 && skip == 0)\n        {\n            loc = 3;\n            skip = 1;\n        }\n        \n        if (global.keyitem[4] == arg0 && skip == 0)\n        {\n            loc = 4;\n            skip = 1;\n        }\n        \n        if (global.keyitem[5] == arg0 && skip == 0)\n        {\n            loc = 5;\n            skip = 1;\n        }\n        \n        if (global.keyitem[6] == arg0 && skip == 0)\n        {\n            loc = 6;\n            skip = 1;\n        }\n        \n        if (global.keyitem[7] == arg0 && skip == 0)\n        {\n            loc = 7;\n            skip = 1;\n        }\n        \n        if (global.keyitem[8] == arg0 && skip == 0)\n        {\n            loc = 8;\n            skip = 1;\n        }\n        \n        if (global.keyitem[9] == arg0 && skip == 0)\n        {\n            loc = 9;\n            skip = 1;\n        }\n        \n        if (global.keyitem[10] == arg0 && skip == 0)\n        {\n            loc = 10;\n            skip = 1;\n        }\n        \n        if (global.keyitem[11] == arg0 && skip == 0)\n        {\n            loc = 11;\n            skip = 1;\n        }\n        \n        scr_keyitemshift(loc, 0);\n        removed = 1;\n    }\n}\n\nfunction scr_keyitemremove_all(arg0)\n{\n    var count = 0;\n    \n    for (var i = 0; i < array_length(global.keyitem); i++)\n    {\n        if (global.keyitem[i] == arg0)\n            count++;\n    }\n    \n    repeat (count)\n        scr_keyitemremove(arg0);\n}\n",
    "scr_become_dark": "function scr_become_dark()\n{\n    global.darkzone = 1;\n    scr_equip_dw_weapon_by_lw_id(global.lweapon);\n    \n    for (var i = 0; i < 8; i++)\n    {\n        var weapon = get_weapon_by_lw_id(global.litem[i]);\n        \n        if (weapon != -4)\n        {\n            if (!scr_weaponcheck_inventory(weapon.dw_id) && !scr_weaponcheck_equipped_any(weapon.dw_id))\n                scr_weaponget(weapon.dw_id);\n        }\n    }\n    \n    global.hp[1] = ceil((global.lhp / global.lmaxhp) * global.maxhp[1]);\n    \n    if (global.hp[1] < 1)\n        global.hp[1] = 1;\n    \n    if (global.hp[1] > global.maxhp[1])\n        global.hp[1] = global.maxhp[1];\n}\n",
    "scr_get_cliff_items": "function scr_get_cliff_items()\n{\n    var boss_list = [];\n    \n    for (var i = 0; i < (global.chapter - 1); i++)\n    {\n        var chapter = i + 1;\n        var boss_result = scr_get_ura_value(chapter, global.filechoice);\n        \n        if (chapter == 4 && boss_result == 1)\n        {\n            boss_result = scr_get_secret_boss_result(chapter);\n            \n            if (boss_result == 0 && scr_completed_chapter(4))\n            {\n                var prev_flag = scr_get_chapter_flag(4, global.filechoice, scr_get_secret_boss_flag(4));\n                boss_result = prev_flag;\n            }\n            \n            if (boss_result == 1)\n                boss_result = 2;\n            \n            scr_set_ura_value(chapter, global.filechoice, boss_result);\n            scr_set_ini_value(chapter, global.filechoice, \"UraBoss\", boss_result);\n        }\n        \n        if (boss_result > 0)\n        {\n            var boss_data = [];\n            \n            if (boss_result == 3)\n            {\n                if (chapter == 2)\n                {\n                    if (boss_result == 3)\n                        boss_result = 2;\n                }\n                else\n                {\n                    boss_result = 1;\n                }\n            }\n            \n            if (chapter == 3)\n            {\n                if (boss_result == 2)\n                    continue;\n            }\n            \n            boss_data[0] = chapter;\n            boss_data[1] = boss_result;\n            boss_list[array_length(boss_list)] = boss_data;\n        }\n    }\n    \n    var pending_items = [];\n    \n    for (var i = 0; i < array_length(boss_list); i++)\n    {\n        var boss_data = boss_list[i];\n        var boss_chapter = boss_data[0];\n        var boss_result = boss_data[1];\n        var boss_item_data = scr_get_boss_item_id(boss_chapter, boss_result);\n        var item_type = boss_item_data[0];\n        var item_id = boss_item_data[1];\n        var have_item = scr_has_boss_item(\"weapon\", item_id) || scr_has_boss_item(\"armor\", item_id);\n        \n        if (boss_chapter == 3 || boss_chapter == 4)\n            have_item = scr_has_boss_item(\"weapon\", item_id);\n        \n        if (!have_item)\n            pending_items[array_length(pending_items)] = boss_item_data;\n    }\n    \n    return pending_items;\n}\n\nfunction scr_has_boss_item(arg0, arg1)\n{\n    var has_item = false;\n    \n    if (arg0 == \"weapon\")\n        has_item = scr_weaponcheck_equipped_any(arg1) || scr_weaponcheck_inventory(arg1);\n    else if (arg0 == \"armor\")\n        has_item = scr_armorcheck_equipped_any(arg1) || scr_armorcheck_inventory(arg1);\n    \n    return has_item;\n}\n\nfunction scr_get_boss_item_id(arg0, arg1)\n{\n    var _chapter = arg0;\n    var _item_type = (arg1 == 1) ? \"weapon\" : \"armor\";\n    var _item_id = -1;\n    \n    switch (_chapter)\n    {\n        case 2:\n            _item_id = 21;\n            break;\n        \n        case 3:\n            _item_id = 26;\n            break;\n        \n        case 4:\n            _item_type = \"weapon\";\n            _item_id = 52;\n            break;\n        \n        default:\n            _item_id = 7;\n            break;\n    }\n    \n    var item_data = [];\n    item_data[0] = _item_type;\n    item_data[1] = _item_id;\n    item_data[2] = _chapter;\n    return item_data;\n}\n\nfunction scr_get_shadow_crystal_flag(arg0)\n{\n    var _chapter = arg0;\n    var _flag = -1;\n    \n    switch (_chapter)\n    {\n        case 1:\n            _flag = 1646;\n            break;\n        \n        case 2:\n            _flag = 1647;\n            break;\n        \n        case 3:\n            _flag = 1648;\n            break;\n        \n        case 4:\n            _flag = 1649;\n            break;\n        \n        case 5:\n            _flag = 1907;\n            break;\n        \n        default:\n            break;\n    }\n    \n    return _flag;\n}\n\nfunction scr_get_shadow_crystal(arg0)\n{\n    var _chapter = arg0;\n    var _flag = scr_get_shadow_crystal_flag(_chapter);\n    \n    if (scr_flag_get(_flag) == 0)\n        scr_flag_set(_flag, 1);\n}\n\nfunction scr_get_total_shadow_crystal_amount()\n{\n    var _amount = 0;\n    var _max_chapter = 5;\n    \n    for (var i = 0; i < _max_chapter; i++)\n    {\n        var _chapter = i + 1;\n        var _flag = scr_get_shadow_crystal_flag(_chapter);\n        _amount += scr_flag_get(_flag);\n    }\n    \n    return _amount;\n}\n",
