    "scr_jump_to_point_sprite": "function scr_jump_to_point_sprite(arg0, arg1, arg2, arg3, arg4, arg5)\n{\n    __jump_to_point = instance_create(x, y, obj_jump_to_point);\n    __jump_to_point.target = id;\n    \n    with (__jump_to_point)\n    {\n        startx = x;\n        starty = y;\n        endx = arg0;\n        endy = arg1;\n        jumpspeed = arg2;\n        jumptime = arg3;\n        jumpsprite = arg4;\n        landsprite = arg5;\n        \n        if (arg4 > 0)\n            usesprites = 1;\n        \n        drawshadow = 0;\n    }\n    \n    return __jump_to_point;\n}\n",
    "button4_p": "function button4_p()\n{\n    var _face = 32771;\n    \n    if (global.input_g[6] == gp_face3)\n        _face = 32772;\n    \n    if (scr_debug() && gamepad_button_check_pressed(obj_gamecontroller.gamepad_id, _face))\n        return 1;\n}\n",
