    "mus_initplay": "function mus_initplay(arg0)\n{\n    global.currentsong[0] = snd_init(arg0);\n    global.currentsong[1] = mus_play(global.currentsong[0]);\n}\n",
    "scr_jump_in_place": "function scr_jump_in_place(arg0, arg1)\n{\n    scr_jump_to_point(x, y, arg0, arg1);\n}\n",
    "c_actortoparty": "function c_actortoparty()\n{\n    c_cmd(\"actortoparty\", 0, 0, 0, 0);\n}\n\nfunction c_actortoparty_function()\n{\n    var actor_count = array_length(actor_id);\n    \n    for (var jjj = 0; jjj < actor_count; jjj++)\n    {\n        if (actor_name[jjj] == \"kris\" && i_ex(actor_id[jjj]))\n        {\n            setxy(actor_id[jjj].x, actor_id[jjj].y, 1198);\n            obj_mainchara.depth = actor_id[jjj].depth;\n            \n            switch (actor_id[jjj].facing)\n            {\n                case \"d\":\n                    global.facing = 0;\n                    break;\n                \n                case \"r\":\n                    global.facing = 1;\n                    break;\n                \n                case \"u\":\n                    global.facing = 2;\n                    break;\n                \n                case \"l\":\n                    global.facing = 3;\n                    break;\n            }\n            \n            obj_mainchara.set_facing();\n            actor_id[jjj].visible = false;\n            obj_mainchara.visible = true;\n        }\n    }\n    \n    for (var lll = 0; lll < 2; lll++)\n    {\n        if (i_ex(global.cinstance[lll]))\n        {\n            for (var jjj = 0; jjj < actor_count; jjj++)\n            {\n                if (actor_name[jjj] == global.cinstance[lll].name && i_ex(actor_id[jjj]))\n                {\n                    var myactor = actor_id[jjj];\n                    \n                    with (obj_caterpillarchara)\n                    {\n                        if (name == myactor.name)\n                        {\n                            setxy(myactor.x, myactor.y);\n                            scr_caterpillar_interpolate(name);\n                            scr_caterpillar_facing_single(name, myactor.facing);\n                            depth = myactor.depth;\n                        }\n                    }\n                    \n                    global.cinstance[lll].visible = 1;\n                    actor_id[jjj].visible = 0;\n                }\n            }\n        }\n    }\n}\n",
    "scr_cutscene_savestate": "function scr_cutscene_savestate()\n{\n    scr_debug_print(\"Cutscene Saved\");\n    masterArray = variable_instance_get_names(id);\n    \n    for (var i = 0; i < array_length_1d(masterArray); i++)\n        myVar[i] = variable_instance_get(id, masterArray[i]);\n    \n    remCameraX = camerax();\n    remCameraY = cameray();\n    \n    for (var i = 0; i < 20; i++)\n    {\n        actorSaved[i] = 0;\n        \n        if (i_ex(actor_id[i]))\n        {\n            actorSaved[i] = 1;\n            \n            with (actor_id[i])\n                scr_instance_save_local_vars();\n        }\n    }\n    \n    for (var i = 0; i < 10; i++)\n    {\n        objectSaved[i] = 0;\n        \n        if (i_ex(save_object[i]))\n        {\n            objectSaved[i] = 1;\n            \n            with (save_object[i])\n                scr_instance_save_local_vars();\n        }\n    }\n    \n    scr_cutscene_save_music();\n}\n",
    "scr_cutscene_loadstate": "function scr_cutscene_loadstate()\n{\n    scr_debug_print(\"Cutscene Loaded\");\n    \n    for (var i = 0; i < 20; i++)\n    {\n        if (i_ex(actor_id[i]))\n        {\n            if (actorSaved[i] == 1)\n            {\n                with (actor_id[i])\n                    scr_instance_load_local_vars();\n            }\n        }\n    }\n    \n    for (var i = 0; i < 10; i++)\n    {\n        if (i_ex(save_object[i]))\n        {\n            if (objectSaved[i] == 1)\n            {\n                with (save_object[i])\n                    scr_instance_load_local_vars();\n            }\n        }\n    }\n    \n    for (var i = 0; i < array_length_1d(masterArray); i++)\n        variable_instance_set(id, masterArray[i], myVar[i]);\n    \n    camerax_set(remCameraX);\n    cameray_set(remCameraY);\n    \n    with (obj_panner)\n        instance_destroy();\n    \n    with (obj_move_actor)\n        instance_destroy();\n    \n    with (obj_move_to_point)\n        instance_destroy();\n    \n    with (obj_shakeobj)\n        instance_destroy();\n    \n    with (obj_shake)\n        instance_destroy();\n    \n    with (obj_dialoguer)\n        instance_destroy();\n    \n    with (obj_writer)\n        instance_destroy();\n    \n    with (obj_face)\n        instance_destroy();\n    \n    with (obj_cutscene_delaycmd)\n        instance_destroy();\n    \n    with (obj_jump_to_point)\n        instance_destroy();\n    \n    with (obj_stickto)\n        instance_destroy();\n    \n    with (obj_lerpvar)\n        instance_destroy();\n    \n    scr_cutscene_load_music();\n    loadedState = 1;\n    waiting = 0;\n    scr_cutscene_master_commands_initialize();\n}\n",
    "scr_animate_complex": "function scr_animate_complex(arg0, arg1, arg2, arg3, arg4 = 0)\n{\n    if (arg4 == \"frames\")\n        arg4 = 0;\n    \n    if (arg4 == \"seconds\")\n        arg4 = 1;\n    \n    var _frames_to_complete = 0;\n    \n    for (var i = 0; i < array_length(arg3); i++)\n    {\n        if (arg4 == 1)\n            arg3[i] = round(arg3[i] * 30);\n        \n        show_debug_message_concat(\"scr_animate_complex: \", _frames_to_complete, \" frames to complete frame: \", arg3[i]);\n        _frames_to_complete += arg3[i];\n    }\n    \n    show_debug_message_concat(\"scr_animate_complex: \", _frames_to_complete, \" frames to complete animation: \", sprite_get_name(arg1));\n    \n    with (instance_create_depth(0, 0, 0, obj_animator_complex))\n    {\n        target = arg0;\n        return_sprite = arg0.sprite_index;\n        sprite = arg1;\n        target.sprite_index = arg1;\n        start_frame = arg2;\n        target.image_index = arg2;\n        timings_array = arg3;\n    }\n    \n    return _frames_to_complete;\n}\n\nfunction c_animate_complex(arg0, arg1, arg2, arg3, arg4 = 0)\n{\n    if (arg4 == \"frames\")\n        arg4 = 0;\n    \n    if (arg4 == \"seconds\")\n        arg4 = 1;\n    \n    var _frames_to_complete = 0;\n    \n    for (var i = 0; i < array_length(arg3); i++)\n    {\n        if (arg4 == 1)\n            arg3[i] = round(arg3[i] * 30);\n        \n        _frames_to_complete += arg3[i];\n    }\n    \n    c_cmd_x(\"animcomplex\", arg0, arg1, arg2, arg3, 0, 0);\n    return _frames_to_complete;\n}\n",
