    "scr_rhythmgame_song_flag": "function scr_rhythmgame_song_flag(arg0, arg1)\n{\n    if (arg0 == 2)\n        return arg1 ? 1667 : 1666;\n    else if (arg0 == 10)\n        return arg1 ? 1669 : 1668;\n    else if (arg0 == 15)\n        return arg1 ? 1673 : 1672;\n    else\n        return arg1 ? 1279 : 1195;\n}\n",
    "mus_play_ext": "function mus_play_ext()\n{\n    global.currentsong[0] = snd_init(argument0);\n    var _vol = 1;\n    \n    if (argument_count >= 3)\n    {\n        if (argument2 != -1)\n            _vol = argument2;\n    }\n    \n    snd_volume(global.currentsong[0], _vol, 0);\n    \n    if (argument_count >= 4)\n    {\n        if (argument3 != -1)\n            snd_pitch(global.currentsong[0], argument3);\n    }\n    \n    var loop = false;\n    \n    if (argument_count >= 2)\n        loop = argument1;\n    \n    if (loop)\n        global.currentsong[1] = mus_loop(global.currentsong[0]);\n    else\n        global.currentsong[1] = mus_play(global.currentsong[0]);\n    \n    if (argument_count >= 5)\n    {\n        if (argument4 != -1)\n            snd_volume(global.currentsong[0], _vol, argument4);\n    }\n    \n    return global.currentsong[1];\n}\n",
    "Vector3": "function Vector3(arg0 = 0, arg1 = 0, arg2 = 0) constructor\n{\n    static add = function(arg0)\n    {\n        x += arg0.x;\n        y += arg0.y;\n        z += arg0.z;\n    };\n    \n    static scale = function(arg0)\n    {\n        x *= arg0.x;\n        y *= arg0.y;\n        z *= arg0.z;\n    };\n    \n    x = arg0;\n    y = arg1;\n    z = arg2;\n    \n    direction = function(arg0, arg1)\n    {\n        return point_direction(0, 0, arg0, arg1);\n    };\n    \n    magnitude = function(arg0, arg1, arg2)\n    {\n        return point_distance_3d(0, 0, 0, arg0, arg1, arg2);\n    };\n    \n    normalized = function(arg0, arg1, arg2)\n    {\n        var __len = point_distance_3d(0, 0, 0, arg0, arg1, arg2);\n        \n        if (arg0 == 0 && arg1 == 0 && arg2 == 0)\n            return new Vector3();\n        \n        return new Vector3(arg0 / __len, arg1 / __len, arg2 / __len);\n    };\n}\n\nfunction getxyz(arg0)\n{\n    return new Vector3(arg0.x, arg0.y, arg0.z);\n}\n\nfunction setxyz_v3(arg0)\n{\n    x = arg0.x;\n    y = arg0.y;\n    z = arg0.z;\n}\n",
    "scr_shopmorearrow": "function scr_shopmorearrow(arg0)\n{\n    if (pagemax > 0)\n        draw_sprite_ext(spr_morearrow, 0, 370, 280 - (sin(cur_jewel / 12) * 3), 1, -1, 0, c_white, 1);\n    \n    if ((5 + pagemax) < arg0)\n    {\n        if (menu == 11)\n        {\n            if (itemsellname[5 + pagemax] != \" \")\n                draw_sprite_ext(spr_morearrow, 0, 370, 440 + (sin(cur_jewel / 12) * 3), 1, 1, 0, c_white, 1);\n        }\n        else\n        {\n            draw_sprite_ext(spr_morearrow, 0, 370, 440 + (sin(cur_jewel / 12) * 3), 1, 1, 0, c_white, 1);\n        }\n    }\n}\n",
