    "scr_instance_save_local_vars": "function scr_instance_save_local_vars()\n{\n    __quickSaved = 1;\n    __masterArray = variable_instance_get_names(id);\n    \n    for (var __n = 0; __n < array_length_1d(__masterArray); __n++)\n    {\n        ___saveSpriteIndex = sprite_index;\n        ___saveImageIndex = image_index;\n        ___saveImageSpeed = image_speed;\n        ___saveXscale = image_xscale;\n        ___saveYscale = image_yscale;\n        ___saveAlpha = image_alpha;\n        ___saveBlend = image_blend;\n        ___saveAngle = image_angle;\n        ___saveX = x;\n        ___saveY = y;\n        ___saveSpeed = speed;\n        ___saveDirection = direction;\n        ___saveDepth = depth;\n        ___saveVisible = visible;\n        ___saveGravity = gravity;\n        ___saveGravityDirection = gravity_direction;\n        ___saveFriction = friction;\n        \n        if (__masterArray[__n] == \"__myVar\")\n            __myVar[__n] = 0;\n        else\n            __myVar[__n] = variable_instance_get(id, __masterArray[__n]);\n    }\n}\n",
    "scr_cutscene_saveload_extra": "function scr_cutscene_save_objects()\n{\n    if (scr_debug())\n    {\n        with (obj_cutscene_master)\n        {\n            var _startslot = 0;\n            \n            for (var i = 0; i < 10; i++)\n            {\n                if (save_object[i] == 99999999 || save_object[i] == -4 || is_undefined(save_object[i]))\n                {\n                    show_debug_message(\"we breakin out of here\");\n                    break;\n                }\n                else\n                {\n                    _startslot++;\n                }\n            }\n            \n            for (var i = 0; i < argument_count; i++)\n            {\n                if ((_startslot + i) >= 10)\n                {\n                    scr_debug_print(\"Cutscene object limit reached.\");\n                    break;\n                }\n                else\n                {\n                    save_object[_startslot + i] = argument[i];\n                }\n            }\n        }\n    }\n}\n\nfunction scr_cutscene_save_song(arg0 = false)\n{\n    with (obj_cutscene_master)\n    {\n        save_mus = true;\n        \n        if (arg0)\n        {\n            if (v_ex(\"save_mus_pos\") && save_mus_pos >= 0)\n                exit;\n            else\n                save_mus_pos = 0;\n        }\n        else\n        {\n            save_mus_pos = -1;\n        }\n    }\n}\n\nfunction scr_cutscene_save_music()\n{\n    if (!v_ex(\"save_mus\") || save_mus == false)\n        exit;\n    \n    if (global.currentsong[1] == -4)\n    {\n        save_mus_track = -4;\n        save_mus_playing = false;\n        save_mus_vol = 1;\n        save_mus_pitch = 1;\n        save_mus_pos = -1;\n    }\n    else\n    {\n        save_mus_track = global.currentsong[0];\n        save_mus_playing = snd_is_playing(global.currentsong[1]);\n        save_mus_pitch = audio_sound_get_pitch(global.currentsong[1]);\n        save_mus_vol = audio_sound_get_gain(global.currentsong[1]);\n        \n        if (v_ex(\"save_mus_pos\") && save_mus_pos >= 0)\n            save_mus_pos = audio_sound_get_track_position(global.currentsong[1]);\n        else\n            save_mus_pos = -1;\n    }\n}\n\nfunction scr_cutscene_load_music()\n{\n    if (!v_ex(\"save_mus\") || save_mus == false)\n        exit;\n    \n    if (global.currentsong[0] != save_mus_track)\n    {\n        if (global.currentsong[0] != -4)\n            snd_stop(global.currentsong[1]);\n        \n        if (save_mus_track != -4)\n        {\n            global.currentsong[0] = snd_init(save_mus_track);\n            global.currentsong[1] = mus_loop(global.currentsong[1]);\n        }\n        else\n        {\n            global.currentsong[0] = -4;\n            global.currentsong[1] = -4;\n        }\n    }\n    \n    if (save_mus_track != -4)\n    {\n        snd_pitch(global.currentsong[1], save_mus_pitch);\n        snd_volume(global.currentsong[1], save_mus_vol, 0);\n        \n        if (save_mus_pos >= 0)\n            audio_sound_set_track_position(global.currentsong[1], save_mus_pos);\n        \n        if (snd_is_playing(global.currentsong[1]) != save_mus_playing)\n        {\n            if (save_mus_playing)\n                audio_resume_sound(global.cuurrentsong[1]);\n            else\n                snd_pause(global.currentsong[1]);\n        }\n    }\n}\n",
    "scr_instance_load_local_vars": "function scr_instance_load_local_vars()\n{\n    for (var __n = 0; __n < array_length_1d(__masterArray); __n++)\n    {\n        sprite_index = ___saveSpriteIndex;\n        image_index = ___saveImageIndex;\n        image_speed = ___saveImageSpeed;\n        image_xscale = ___saveXscale;\n        image_yscale = ___saveYscale;\n        image_alpha = ___saveAlpha;\n        image_blend = ___saveBlend;\n        image_angle = ___saveAngle;\n        x = ___saveX;\n        y = ___saveY;\n        speed = ___saveSpeed;\n        direction = ___saveDirection;\n        depth = ___saveDepth;\n        visible = ___saveVisible;\n        gravity = ___saveGravity;\n        gravity_direction = ___saveGravityDirection;\n        friction = ___saveFriction;\n        \n        if (__masterArray[__n] != \"__myVar\" && __masterArray[__n] != \"__masterArray\")\n            variable_instance_set(id, __masterArray[__n], __myVar[__n]);\n    }\n}\n",
